      return new Promise(function (resolve) {
        var reader = new FileReader();
        reader.onload = function () { resolve(String(reader.result || "")); };
        reader.onerror = function () { resolve(""); };
        reader.readAsText(file);
      });
    }
    return new Promise(function (resolve) {
      var reader = new FileReader();
      reader.onload = function () {
        window.JSZip.loadAsync(reader.result).then(function (zip) {
          var commentsFile = zip.file("word/comments.xml");
          var documentFile = zip.file("word/document.xml");
          var commentsPromise = commentsFile ? commentsFile.async("string") : Promise.resolve("");
          var documentPromise = documentFile ? documentFile.async("string") : Promise.resolve("");
          return Promise.all([commentsPromise, documentPromise]);
        }).then(function (parts) {
          var commentsXml = parts[0];
          var docXml = parts[1];
          var out = "";
          if (commentsXml) {
            // Extract comment text from <w:comment> elements.
            var commentMatches = commentsXml.match(/<w:comment\b[^>]*>[\s\S]*?<\/w:comment>/g) || [];
            commentMatches.forEach(function (block) {
              var authorMatch = block.match(/w:author="([^"]+)"/);
              var author = authorMatch ? authorMatch[1] : "Unknown";
              var textMatches = block.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
              var text = textMatches.map(function (t) {
                return t.replace(/<w:t[^>]*>/, "").replace(/<\/w:t>/, "");
              }).join("");
              if (text) out += author + ": " + text + "\n\n";
            });
          }
          if (docXml) {
            // Extract body paragraphs as plain text.
            var paraMatches = docXml.match(/<w:p\b[^>]*>[\s\S]*?<\/w:p>/g) || [];
            var bodyText = paraMatches.map(function (p) {
              var textMatches = p.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
              return textMatches.map(function (t) {
                return t.replace(/<w:t[^>]*>/, "").replace(/<\/w:t>/, "");
              }).join("");
            }).filter(Boolean).join("\n");
            if (bodyText) out += "\n--- BODY TEXT ---\n" + bodyText;
          }
          resolve(out);
        }).catch(function (err) {
          _toast("Couldn't parse .docx: " + (err && err.message), "err");
          resolve("");
        });
      };
      reader.onerror = function () { resolve(""); };
      reader.readAsArrayBuffer(file);
    });
  }
  // Extract Word comments from the open doc via Office.js.
  function _readDocComments() {
    if (!eli.host || typeof eli.host.runRaw !== "function") return Promise.resolve("");
    return eli.host.runRaw("eli_agent:read_comments", function (context) {
      var comments = context.document.body.getComments();
      comments.load("items/content,items/authorName");
      return context.sync().then(function () {
        var items = comments.items || [];
        if (!items.length) return "";
        return items.map(function (c) {
          var author = c.authorName || "Unknown";
          var content = String(c.content || "").trim();
          if (!content) return "";
          return author + ": " + content;
        }).filter(Boolean).join("\n\n");
      });
    }).catch(function () { return ""; });
  }
  // Simple toast wrapper — falls back to console.
  function _toast(msg, kind) {
    if (typeof window.showToast === "function") {
      try { window.showToast(msg, kind || "info"); return; } catch (_) {}
    }
    eli.log.event("tool", "eli_agent_toast", { msg: msg, kind: kind });
  }

