  // ─── Draft Document: interview pane ─────────────────────────────
  // Conversational Q&A. Each turn = an agent question + the user's
  // answer. After 3-5 turns the agent decides intake is sufficient
  // and offers a "Generate Draft" button.
  function _bodyInterview() {
    var iv = _egActive.interview || {};
    var turns = iv.turns || [];
    var seed = iv.seed || "";
    var turnsHtml = (seed ? '<div class="_eg_iv_turn _eg_iv_user"><div class="_eg_iv_role">YOU</div><div class="_eg_iv_text">' + _esc(seed) + '</div></div>' : "") +
      turns.map(function (t) {
        var qHtml = '<div class="_eg_iv_turn _eg_iv_agent"><div class="_eg_iv_role">📝 AGENT</div><div class="_eg_iv_text">' + _esc(t.question || "") + '</div></div>';
        var aHtml = '';
        if (t.answer) {
          aHtml = '<div class="_eg_iv_turn _eg_iv_user"><div class="_eg_iv_role">YOU</div><div class="_eg_iv_text">' + _esc(t.answer) + '</div></div>';
        }
        return qHtml + aHtml;
      }).join("");
    // The pending agent question (waiting for user answer).
    var pending = iv.nextQuestions && iv.nextQuestions.length ? iv.nextQuestions[0] : null;
    var inputArea = "";
    if (pending) {
      var qHtml = '<div class="_eg_iv_turn _eg_iv_agent"><div class="_eg_iv_role">📝 AGENT</div><div class="_eg_iv_text">' + _esc(pending.question || "") + '</div></div>';
      // Render input based on question type.
      if (pending.type === "choice" && Array.isArray(pending.options) && pending.options.length) {
        inputArea = qHtml +
          '<div class="_eg_iv_choices">' +
            pending.options.map(function (o) {
              return '<button type="button" class="_eg_btn_secondary _eg_iv_choice_btn" data-eg-iv-choice="' + _esc(o) + '">' + _esc(o) + '</button>';
            }).join("") +
          '</div>' +
          '<div class="_eg_iv_input_row">' +
            '<input id="_eg_iv_text_input" type="text" class="_eg_iv_text_input" placeholder="…or type a custom answer" />' +
            '<button id="_eg_iv_submit" type="button" class="_eg_btn_primary">Send</button>' +
          '</div>';
      } else {
        inputArea = qHtml +
          '<div class="_eg_iv_input_row">' +
            '<input id="_eg_iv_text_input" type="text" class="_eg_iv_text_input" placeholder="Type your answer…" autofocus />' +
            '<button id="_eg_iv_submit" type="button" class="_eg_btn_primary">Send</button>' +
          '</div>';
      }
    } else if (iv.thinking) {
      // The gap this fills: between sending an answer and the next question
      // arriving there is an AI call, and every branch below used to be
      // false — so the pane went blank and the thread appeared to stop.
      inputArea =
        '<div class="_eg_iv_turn _eg_iv_agent _eg_iv_thinking">' +
          '<div class="_eg_iv_role">📝 AGENT</div>' +
          '<div class="_eg_iv_text">' +
            (turns.length ? "Reading your answer" : "Preparing the first question") +
            '<i class="_eg_st_ell"><b></b><b></b><b></b></i>' +
          '</div>' +
        '</div>';
    } else if (iv.intakeComplete) {
      // Ready to draft. Said in the thread, not only on the button: the
      // turn that ENDS the interview should read like the ones before it,
      // or the questions just stop and a button appears.
      inputArea =
        '<div class="_eg_iv_turn _eg_iv_agent">' +
          '<div class="_eg_iv_role">📝 AGENT</div>' +
          '<div class="_eg_iv_text">That is enough to start' +
            (iv.agreementType ? " the " + _esc(iv.agreementType) : " drafting") +
            '. I will settle the full structure first, check it for anything ' +
            'missing, then draft each part — you see the outline before a ' +
            'word is written.</div>' +
        '</div>' +
        '<div class="_eg_actions_row _eg_actions_sticky">' +
          '<button id="_eg_iv_more" type="button" class="_eg_btn_secondary">Add more context</button>' +
          '<button id="_eg_iv_draft" type="button" class="_eg_btn_primary _eg_btn_apply">Generate Draft →</button>' +
        '</div>';
    }
    // The tail is what the reader must be looking at after every turn: the
    // newest question and the box to answer it, or the thinking row.
    return _bodyHeader() +
      _stageStrip() +
      '<div class="_eg_iv_thread">' + turnsHtml + '</div>' +
      '<div id="_eg_iv_tail">' + inputArea + '</div>';
  }
  function _wireInterviewControls(body) {
    // First time: kick off the interview if no questions yet. `thinking`
    // is part of the guard because _runInterviewTurn now repaints to show
    // the waiting row, and this wiring runs again on that repaint.
    var iv = _egActive.interview;
    if (!iv.turns.length && !iv.nextQuestions && !iv.intakeComplete && !iv.thinking) {
      _runInterviewTurn("");  // initial — no answer to process
      return;
    }
    // Choice buttons.
    body.querySelectorAll("[data-eg-iv-choice]").forEach(function (btn) {
      btn.onclick = function () {
        var answer = btn.getAttribute("data-eg-iv-choice");
        _submitInterviewAnswer(answer);
      };
    });
    // Free-text input + Send.
    var textInput = body.querySelector("#_eg_iv_text_input");
    var sendBtn = body.querySelector("#_eg_iv_submit");
    if (sendBtn) sendBtn.onclick = function () {
      var v = textInput ? (textInput.value || "").trim() : "";
      if (!v) return;
      _submitInterviewAnswer(v);
    };
    if (textInput) {
      textInput.onkeydown = function (e) {
        if (e.key === "Enter") { e.preventDefault(); if (sendBtn) sendBtn.click(); }
      };
      try { textInput.focus(); } catch (_) {}
    }
    // Post-intake actions.
    var draftBtn = body.querySelector("#_eg_iv_draft");
    if (draftBtn) draftBtn.onclick = function () { _runDraftPipeline(); };
    var moreBtn = body.querySelector("#_eg_iv_more");
    if (moreBtn) moreBtn.onclick = function () {
      _egActive.interview.intakeComplete = false;
      _runInterviewTurn(null);  // ask another question
    };
    // Follow the thread. The screen-level scroll only fires on ENTERING a
    // screen, and the interview stays on one screen for every turn — so
    // each new question arrived below the fold and the pane looked stuck.
    //
    // "end" on the last turn, "nearest" on every other. Generate Draft is
    // the one thing here the reader has to find, and "nearest" leaves it
    // wherever it already was — which is how you finish answering and see
    // nothing happen. Its scroll-margin-bottom keeps it clear of the
    // chat's input bar.
    _scrollSoon(body.querySelector("#_eg_iv_tail"),
      iv.intakeComplete ? "end" : "nearest");
  }
  function _submitInterviewAnswer(answer) {
    var iv = _egActive.interview;
    var pending = iv.nextQuestions && iv.nextQuestions[0];
    if (!pending) return;
    iv.turns.push({ question: pending.question, answer: String(answer), type: pending.type || "text" });
    iv.nextQuestions = iv.nextQuestions.slice(1);
    // One repaint, not two: _runInterviewTurn paints the waiting row
    // itself, and painting before it showed the answer with nothing under
    // it for a frame.
    if (iv.nextQuestions.length) _renderOverlayBody();
    else _runInterviewTurn(answer);  // get next question(s) from agent
  }
  // Ask the AI for the next intake question (or signal intake is done).
  function _runInterviewTurn(lastAnswer) {
    if (!_egActive) return;
    var prompt = _buildInterviewTurnPrompt(_egActive, lastAnswer);
    _egActive.interview.thinking = true;
    _renderOverlayBody();
    _aiJsonCall(prompt, { intakeComplete: "boolean", questions: "object", agreementType: "string" })
      .then(function (result) {
        if (!_egActive) return;
        _egActive.interview.thinking = false;
        if (result && result.intakeComplete) {
          _egActive.interview.intakeComplete = true;
          _egActive.interview.nextQuestions = null;
          if (result.agreementType) _egActive.interview.agreementType = result.agreementType;
        } else if (result && Array.isArray(result.questions) && result.questions.length) {
          _egActive.interview.nextQuestions = result.questions;
          if (result.agreementType && !_egActive.interview.agreementType) {
            _egActive.interview.agreementType = result.agreementType;
          }
        } else {
          // Empty result — treat as intake complete to avoid getting stuck.
          _egActive.interview.intakeComplete = true;
        }
        _renderOverlayBody();
      })
      .catch(function (err) {
        if (_egActive) _egActive.interview.thinking = false;
        _egActive.status = "error";
        _egActive.error = (err && err.message) || String(err);
        _renderOverlayBody();
      });
  }

  // ─── Draft Document: outline review ─────────────────────────────
  // A one-word badge saying where this section's language comes from. The
  // whole point of retrieval is that a reader can see, before drafting
  // starts, how much of the document is our own reviewed language and how
  // much the model is about to invent.
  var RET_LABEL = {
    locked: { text: "Playbook (locked)", cls: "_eg_src_locked" },
    playbook: { text: "Playbook", cls: "_eg_src_playbook" },
    template: { text: "Our template", cls: "_eg_src_template" },
    adapt: { text: "Adapted", cls: "_eg_src_adapt" },
    generate: { text: "Newly drafted", cls: "_eg_src_generate" },
