    if (proceedBtn) proceedBtn.onclick = _runSectionDrafting;
  }

  // ─── Draft Document: drafting progress + review ─────────────────
  // What each state says for itself. The old screen marked EVERY section
  // "drafting" before the first call went out, so thirty rows sat on ⚙
  // "drafting…" for the whole run and nothing appeared to move — only three
  // are ever actually in flight.
  var DRAFT_ROW = {
    done:     { icon: "✓", word: "drafted" },
    failed:   { icon: "⚠", word: "failed" },
    drafting: { icon: "⚙", word: "drafting" },
    queued:   { icon: "○", word: "queued" },
  };
  function _bodyDrafting() {
    var sections = _egActive.outline || [];
    var done = 0, firstLive = "";
    var rows = sections.map(function (s) {
      var st = s.status || "queued";
      var r = DRAFT_ROW[st] || DRAFT_ROW.queued;
      if (st === "done") done++;
      // The anchor is the first row still working, so the list follows the
