          _stInsertMissing(_egActive.outline, m);
          _egActive.structureAdded.push(m.name);
          _egActive.draftAcceptance[_egActive.outline.filter(function (x) {
            return _dcNorm(x.name) === _dcNorm(m.name);
          })[0].id] = "accept";
          _stream("found", "Missing: " + m.name, m.why || "");
        });
