  // House format. Times New Roman 11 on everything ELI writes, so an
  // inserted draft matches the documents around it; the title, the recitals
  // header and every section heading centred; clause titles bold.
  function _diApplyStyles(context, made) {
    made.forEach(function (m) {
      try { m.p.font.name = "Times New Roman"; m.p.font.size = 11; } catch (_e) {}
