      // contract heading so navigation and the clause indexer still see it,
      // but ranged left — a centred heading inside a memo reads as a title
      // for the whole document rather than a heading for what follows.
      if (m.kind === "subhead") {
        try { m.p.styleBuiltIn = Word.Style.heading2; } catch (_e15) {
          try { m.p.style = "Heading 2"; } catch (_e16) {}
        }
        try {
          m.p.font.name = "Times New Roman";
          m.p.font.size = 11;
