      var lines = para.split("\n");
      // A heading on its own line.
      var h = lines.length === 1 && lines[0].match(/^(#{1,4})\s+(.+)$/);
      if (h) return '<div class="_eg_md_h">' + _mdInline(h[2]) + "</div>";
