          return "<li>" + _mdInline(l.replace(/^\s*[-*•]\s+/, "")) + "</li>";
        }).join("") + "</ul>";
      }
      if (lines.every(function (l) { return /^\s*\d+[.)]\s+/.test(l); })) {
