      // gluing a heading to the paragraph under it.
      return "<p>" + lines.map(function (l) {
        var hh = l.match(/^(#{1,4})\s+(.+)$/);
        if (hh) return '<span class="_eg_md_h">' + _mdInline(hh[2]) + "</span>";
