  // Validate + normalize the plan returned by the AI. Drops malformed
  // edits (missing required fields) rather than failing the whole plan.
  // Cross-references paragraphId against the qaIndex to:
  //   • infer `section` when the AI omitted it
  //   • compute paragraphIndex (1-based position in doc) for the
  //     "Paragraph N of M" footer line on each card
  // Malformed edits are dropped in three places inside _validatePlan, which
  // runs three times per plan. Collected here so the count reaches the review
  // instead of only the difference between two numbers nobody sees.
  // Turn a literal backslash-n / backslash-r / backslash-t into the real
  // character. Built with fromCharCode so no patch script can collapse the
  // escape — this exact line has been mangled before.
  var BSLASH = String.fromCharCode(92);
  var RE_LIT_BREAK = new RegExp(BSLASH + BSLASH + "+[nrt]", "g");
  function _unescapeBreaks(v) {
    var s = String(v == null ? "" : v);
    if (s.indexOf(BSLASH) === -1) return s;
    return s.replace(RE_LIT_BREAK, function (m) {
      var last = m.charAt(m.length - 1);
      if (last === "n") return "\n";
      if (last === "r") return "\r";
      return " ";                                   // a literal \t reads as a space
    });
  }

  function _noteMalformed(why) {
    if (!_egActive) return;
    (_egActive.malformedDropped = _egActive.malformedDropped || []).push(why);
  }
  function _validatePlan(plan) {
    if (!plan || typeof plan !== "object") {
      return { summary: "", edits: [] };
    }
    var edits = Array.isArray(plan.edits) ? plan.edits : [];
    var validated = [];
    var seenIds = {};
    // Build paragraphId → {section, index1Based} lookup from the qaIndex.
    var qaIndex = (_egActive && _egActive.qaIndex) || [];
    var paraLookup = {};
    qaIndex.forEach(function (p, i) {
      if (p && p.id) paraLookup[p.id] = { section: p.section || null, index: i + 1, text: p.text || "" };
    });
    var totalParas = qaIndex.length;
    edits.forEach(function (e, idx) {
      if (!e || typeof e !== "object") { _noteMalformed("not an edit object"); return; }
      var id = String(e.id || ("e" + (idx + 1)));
      if (seenIds[id]) id = id + "_" + idx;
      seenIds[id] = true;
      var type = e.type === "insert" || e.type === "delete" ? e.type : "replace";
      var hasAnchor = typeof e.anchorText === "string" && e.anchorText.trim().length > 0;
      // Silently skipped until 2026-09-15. A model that wrote an edit
      // without quotable anchor text had it vanish between stages with no
      // count anywhere — the same invisible-deletion problem as critique.
      if (!hasAnchor) { _noteMalformed(id + ": no anchor text"); return; }
      if (type !== "delete") {
        var hasReplacement = typeof e.replacementText === "string" && e.replacementText.trim().length > 0;
        if (!hasReplacement) { _noteMalformed(id + ": no replacement text"); return; }
      }
      // The model sometimes DOUBLE-escapes a newline, so the JSON string
      // carries the two characters backslash-n rather than a line break.
      // Those survive into the document verbatim — "…consent.\n\nNotices."
      // — because insertText writes exactly what it is given. No contract
      // clause contains a literal backslash-n, so turning them into real
      // breaks is safe, and _insertMultiline then writes them properly.
      e.anchorText = _unescapeBreaks(e.anchorText);
      e.replacementText = _unescapeBreaks(e.replacementText);
      var aiParaId = typeof e.paragraphId === "string" ? e.paragraphId : null;
      var aiSection = typeof e.section === "string" ? e.section.trim() : "";
      // Re-derive paragraphId from anchorText — don't trust the AI's
      // claimed paragraphId. The AI frequently mis-attributes an edit
      // to the wrong paragraph (it sees "thirty (30) days" mentioned
      // in multiple places — definition + operative clause + cross-ref
      // — and picks an id that doesn't match where the actual anchor
      // text lives). That mis-attribution then causes both wrong-
      // section labels AND apply-failure.
      // Strategy: search the qaIndex for the paragraph whose `text`
      // actually contains anchorText. Prefer AI's claimed id if it's
      // among the matches (multiple hits → AI probably picked the
      // intended one). Fall back to first match. Final fallback: AI's
      // claimed id (lookup may still hit a real section).
      var anchorLower = String(e.anchorText || "").toLowerCase().replace(/\s+/g, " ").trim();
      var resolvedParaId = aiParaId;
      var matchedIds = [];
      if (anchorLower) {
        for (var qi = 0; qi < qaIndex.length; qi++) {
          var q = qaIndex[qi];
          if (!q || !q.id || !q.text) continue;
          var qTextNorm = String(q.text).toLowerCase().replace(/\s+/g, " ");
          if (qTextNorm.indexOf(anchorLower) !== -1) {
            matchedIds.push(q.id);
          }
        }
      }
      if (matchedIds.length) {
        // Prefer AI's claim if it's in the match set — AI knew the
        // right paragraph among multiple containing the anchor.
        if (aiParaId && matchedIds.indexOf(aiParaId) !== -1) {
          resolvedParaId = aiParaId;
        } else {
          // AI's claim isn't in the match set — override with first
          // real match. Log so we can monitor how often AI is wrong.
          resolvedParaId = matchedIds[0];
          if (aiParaId && aiParaId !== resolvedParaId) {
            try {
              eli.log.event("tool", "eli_agent_paraId_corrected", {
                aiParaId: aiParaId,
                resolvedParaId: resolvedParaId,
                anchorPreview: anchorLower.slice(0, 60),
                matchCount: matchedIds.length,
              });
            } catch (_) {}
          }
        }
      }
      // Re-do the lookup with the (possibly corrected) paragraphId.
      var paraId = resolvedParaId;
      var lookup = paraId ? paraLookup[paraId] : null;
      var lookupSection = lookup && lookup.section ? String(lookup.section).trim() : "";
      var resolvedSection = lookupSection || null;
      if (aiSection && lookupSection && aiSection !== lookupSection) {
        try {
          eli.log.event("tool", "eli_agent_section_mismatch", {
            paragraphId: paraId,
            aiSection: aiSection,
            lookupSection: lookupSection,
          });
        } catch (_) {}
      }
      validated.push({
        id: id,
        type: type,
        paragraphId: paraId,
        paragraphIndex: lookup ? lookup.index : null,
        paragraphTotal: totalParas || null,
        paragraphText: lookup ? lookup.text : null,  // for inline-redline render
        section: resolvedSection,
        anchorText: e.anchorText,
        replacementText: typeof e.replacementText === "string" ? e.replacementText : null,
        insertPosition: e.insertPosition === "before" ? "before" : "after",
        rationale: typeof e.rationale === "string" ? e.rationale : "",
        category: typeof e.category === "string" ? e.category : "other",
        confidence: Math.max(1, Math.min(5, parseInt(e.confidence, 10) || 3)),
        requiresHumanReview: !!e.requiresHumanReview,
        // Critique-pass enrichment fields. Empty until the critique
        // pass completes; UI conditionally shows them.
        bucket: typeof e.bucket === "string" ? e.bucket : null,
        // Email-agent linkage — set by per-comment bucket prompts so
        // the review UI can show "addresses comment c3 from Sarah."
        addressesComment: typeof e.addressesComment === "string" ? e.addressesComment : null,
      });
    });
    return { summary: typeof plan.summary === "string" ? plan.summary : "", edits: validated };
  }
  // Kernel completeJSON schema is a top-level shape map ({key: "type"}),
  // not full JSON Schema. We rely on the prompt to enforce the actual
  // structure, then _validatePlan does deep normalization. The schema
  // here just catches catastrophic shape failures (AI returns a string
  // instead of an object).
  var PLAN_SCHEMA = { summary: "string", edits: "object" };

  // ─── Card scroll-flash (mini-map + strategy pill click) ──────────
  function _flashCard(editId) {
    var el = document.getElementById("_eg_card_" + editId);
    if (!el) return;
