        // anchor — that mismatch is what sent the kernel helper hunting for
        // strings the document does not contain.
        var d = _diffEnds(actual, repl);
        if (!d.oldMid && !d.newMid) { edit._step = "noop"; edit._noChange = true; return; }
        // Only the provably safe case takes the precise path. Everything
        // else replaces the span, which cannot fail.
        if (!d.oldMid || !d.newMid) return whole();          // pure insert or delete
        if (d.oldMid.length > SEARCH_MAX) return whole();
        if (_hasLineBreak(d.oldMid)) return whole();         // Word rejects the search
        if (actual.split(d.oldMid).length - 1 !== 1) return whole();   // not unique
        edit._step = "span.minimal(mid=" + d.oldMid.length + ")";
        var hits = range.search(d.oldMid, { matchCase: true });
        hits.load("items");
        return context.sync().then(function () {
          if (!hits.items || hits.items.length !== 1) return whole();
          var sub = hits.items[0];
          sub.font.load("bold, italic, underline, color, name, size");
          return context.sync().then(function () {
            var snap = { bold: sub.font.bold, italic: sub.font.italic,
              underline: sub.font.underline, color: sub.font.color,
              name: sub.font.name, size: sub.font.size };
            // Word for Web returns undefined from insertText on some builds;
            // the original range then covers the new text.
            var out = sub.insertText(d.newMid, "Replace") || sub;
            try {
              if (typeof snap.bold === "boolean") out.font.bold = snap.bold;
              if (typeof snap.italic === "boolean") out.font.italic = snap.italic;
              // underline is a string enum ("Single"/"None"), not a boolean.
              if (typeof snap.underline === "string" && snap.underline) out.font.underline = snap.underline;
              if (snap.color) out.font.color = snap.color;
              if (snap.name) out.font.name = snap.name;
              if (snap.size > 0) out.font.size = snap.size;
            } catch (_) { /* formatting is the nicety, not the edit */ }
            edit._appliedPrecision = "minimal";
            return context.sync();
          });
        }).catch(function () {
          // Pre-checks said this search was safe and it was not. Fall back
          // rather than surface a failure the user cannot act on.
          edit._minimalFellBack = true;
          return whole();
        });
      });
    }
    var appliedEdits = [];  // successful edits — surfaced on _bodyApplied
    function _runChain(idx) {
      if (idx >= accepted.length) {
        // A subset applied from the review stays on the review — mark those
        // cards done and repaint, rather than jumping to the summary and
        // losing the list the user is working through.
        if (subset) {
          appliedEdits.forEach(function (e) { _egActive.acceptance[e.id] = "applied"; });
          _egActive.subsetFailures = (_egActive.subsetFailures || []).concat(failures);
          _renderOverlayBody();
          // One card that inserts a clause shifts every later paragraph
          // just as much as applying them all does.
          _reindexAfterStructuralChange(appliedEdits).then(function () {
            if (failures.length && (_egActive || {}).requirements &&
                _egActive.requirements.length) _runPostApplyAudit();
          });
          return;
        }
        _egActive.applyResult = {
          applied: applied,
          failures: failures,
          appliedEdits: appliedEdits,
        };
        _egActive.status = "applied";
        _renderOverlayBody();
        // An insert or delete changes how many paragraphs there are, so
        // every cached index — ours, the kernel's structural map, ask_eli's
        // — now describes a document that no longer exists. Re-read before
        // anything else (a re-plan, the post-apply audit, a Locate) works
        // from ids that have shifted underneath it.
        eli.log.event("tool", "eli_agent_apply_complete", {
          agent: _egActive.agent,
          applied: applied,
          failed: failures.length,
        });
        // Re-index FIRST, then audit — the audit reads the document, and
        // reading it through a stale index is the thing being fixed.
        _reindexAfterStructuralChange(appliedEdits).then(function () {
          // An edit that failed means the audited simulation is not what
          // landed, so the "covered" verdict standing on screen is about a
          // document that does not exist. Re-check against the real one.
          if (_egActive && failures.length &&
              (_egActive.requirements || []).length) _runPostApplyAudit();
        });
        return;
      }
      var edit = accepted[idx];
      _applyOne(edit).then(function () {
        applied++;
        appliedEdits.push(edit);
        _stream("ok", "Applied " + (edit.section || edit.id));
      }, function (err) {
        // Record WHICH Word call threw and what it was handed. A bare
        // "InvalidArgument" says nothing; "insertParagraph(len=0)" says
        // everything, and these failures are otherwise unreproducible.
        var detail = {
          step: edit._step || "unknown",
          precision: edit._precision || "?",
          wholeParagraph: !!edit._wholeParagraph,
          anchorLen: String(edit.anchorText || "").length,
          anchoredLen: String(edit._anchoredText || "").length,
          replLen: String(edit.replacementText || "").length,
          occurrences: edit._occurrences,
          // How a long anchor was located: joined from its two ends, or
          // applied by rebuilding the paragraph. Both are otherwise
          // invisible, and they are the paths most worth knowing about
          // when one of these fails.
          spanJoined: edit._spanJoined ? edit._spanJoined.anchor : 0,
          paragraphRebuilt: !!edit._rewroteParagraph,
        };
        failures.push({
          edit: edit,
          reason: (err && err.message) || String(err),
          detail: detail,
        });
        _stream("warn", "Could not apply " + (edit.section || edit.id),
          (err && err.message) || String(err));
        if (eli.log && typeof eli.log.event === "function") {
          eli.log.event("tool", "eli_agent_apply_failed",
            Object.assign({ msg: (err && err.message) || String(err) }, detail));
        }
      }).then(function () {
        _runChain(idx + 1);
      });
    }
    _runChain(0);
  }

  // ─── Manage Agents modal ──────────────────────────────────────────
  // Barebones V1: list every registered agent with an enable toggle
  // and the agent's description. Tone/scope controls render but only
  // tone is editable in V1 (scope checkboxes ship in Phase 2 once the
  // planning prompt actually consumes them).
  function _openManageAgentsModal() {
    _closeManageAgentsModal();
    var modal = document.createElement("div");
    modal.id = "_eg_manage_modal";
    modal.className = "_eg_modal_backdrop";
    modal.innerHTML =
      '<div class="_eg_modal_panel">' +
        '<div class="_eg_modal_header">' +
          '<div class="_eg_modal_title">⚙ Manage Agents</div>' +
          '<button id="_eg_manage_close" type="button" class="_eg_btn_ghost">✕</button>' +
        '</div>' +
        '<div id="_eg_manage_body" class="_eg_modal_body">' +
          '<div style="font-size:11px;color:#64748b;text-align:center;padding:24px;">Loading agents…</div>' +
        '</div>' +
      '</div>';
    document.body.appendChild(modal);
    document.getElementById("_eg_manage_close").onclick = _closeManageAgentsModal;
    modal.onclick = function (ev) { if (ev.target === modal) _closeManageAgentsModal(); };
    _renderManageAgentsBody();
  }
  function _renderManageAgentsBody() {
    var body = document.getElementById("_eg_manage_body");
    if (!body) return;
    Promise.all(AGENT_REGISTRY.map(function (a) {
      return _getAgentSettings(a.id).then(function (s) { return { agent: a, settings: s }; });
    })).then(function (rows) {
      var html = '';
      rows.forEach(function (row) {
        var enabled = row.settings.enabled !== false;
        var tone = row.settings.tone || "balanced";
        html +=
          '<div class="_eg_manage_card">' +
            '<div class="_eg_manage_card_head">' +
              '<div class="_eg_manage_card_title">' +
                '<span style="font-size:18px;">' + _esc(row.agent.icon) + '</span>' +
                '<span>' + _esc(row.agent.displayName) + '</span>' +
              '</div>' +
              '<label class="_eg_toggle">' +
                '<input type="checkbox" data-eg-toggle-agent="' + _esc(row.agent.id) + '"' + (enabled ? ' checked' : '') + '>' +
                '<span>' + (enabled ? 'Enabled' : 'Disabled') + '</span>' +
              '</label>' +
            '</div>' +
            '<div class="_eg_manage_card_desc">' + _esc(row.agent.description) + '</div>' +
            '<div class="_eg_manage_card_settings">' +
              '<label class="_eg_setting_label">Default tone</label>' +
              '<select data-eg-tone="' + _esc(row.agent.id) + '">' +
                '<option value="conservative"' + (tone === "conservative" ? ' selected' : '') + '>Conservative</option>' +
                '<option value="balanced"' + (tone === "balanced" ? ' selected' : '') + '>Balanced</option>' +
                '<option value="aggressive"' + (tone === "aggressive" ? ' selected' : '') + '>Aggressive</option>' +
              '</select>' +
            '</div>' +
          '</div>';
      });
      body.innerHTML = html + '<div id="_eg_cl_panel" class="_eg_manage_card"></div>';
      _wireManageAgentsControls();
      _renderClausePanel();
    }).catch(function (err) {
      body.innerHTML = '<div style="font-size:11px;color:#991b1b;padding:24px;text-align:center;">Failed to load agents: ' + _esc(err && err.message) + '</div>';
    });
  }
  // The shape the parser saw, shown when a template yields nothing. Without
  // it "no clauses found" is a dead end — this says whether the OOXML even
  // parsed, and what the headings actually look like.
  function _clDiagHtml(d) {
    if (!d) return "";
    var shape = d.looksPackage ? "flat-OPC package" : (d.looksDocument ? "w:document" : "unrecognised");
    var rows =
      '<div class="_eg_cl_diag">' +
        '<div>' + _esc(shape) + ', ' + d.bytes.toLocaleString() + ' chars — ' +
          d.paras + ' paragraphs (' + d.nonEmpty + ' with text, ' + d.inTable + ' in tables)</div>' +
        '<div>raw &lt;w:p&gt; in the text: ' + (d.rawParas || 0) +
          ' · w:body present: ' + (d.rawBody ? "yes" : "no") +
          ' · pkg:part elements: ' + (d.parts === undefined ? "?" : d.parts) +
          ' · root: ' + _esc(String(d.rootName || "?")) + '</div>' +
        (d.parseError
          ? '<div><b>XML parse error:</b> ' + _esc(d.parseError) + '</div>'
          : '<div>XML parsed without error</div>') +
        (d.prolog ? '<div>starts: ' + _esc(d.prolog) + '</div>' : "") +
        '<div>' + d.headings + ' detected as headings · ' + d.withOutline +
          ' with outline level · ' + d.withNumbering + ' auto-numbered</div>';
    if (d.styles && d.styles.length) {
      rows += '<div>styles: ' + d.styles.map(function (s) {
        return _esc(s.style) + '×' + s.n;
      }).join(", ") + '</div>';
    }
    if (d.samples && d.samples.length) {
      rows += '<div class="_eg_cl_diag_samples">' + d.samples.map(function (s) {
        return '<div><span class="_eg_cl_dim">[' + _esc(s.style) +
          (s.outline >= 0 ? ' o' + s.outline : '') + (s.numbered ? ' num' : '') +
          ' lvl' + s.level + ']</span> ' + _esc(s.text) + '</div>';
      }).join("") + '</div>';
    }
    return rows + '</div>';
  }

  // Clause library panel — builds the index the drafting agent retrieves
  // from, so a draft reuses vetted language instead of generating prose.
  function _renderClausePanel(report) {
    var el = document.getElementById("_eg_cl_panel");
    if (!el) return;
    _clReadManifest().then(function (man) {
      var tpls = (man && man.templates) || [];
      var status;
      if (report && report.missing && report.missing.length) {
        status = '<div class="_eg_cl_warn">' +
          report.missing.map(function (m) {
            return '<div>' + _esc(m.label) + ' — not indexed: ' + _esc(m.reason) + '</div>' +
              _clDiagHtml(m.diag);
          }).join("") + '</div>';
      } else { status = ""; }
      var listed = tpls.length
        ? '<ul class="_eg_cl_list">' + tpls.map(function (x) {
            return '<li><b>' + _esc(x.templateName) + '</b> — ' +
              x.cardCount + ' clause' + (x.cardCount === 1 ? '' : 's') +
              (x.agreementType ? ' <span class="_eg_cl_dim">(' + _esc(x.agreementType) + ')</span>' : '') +
            '</li>';
          }).join("") + '</ul>' +
          '<div class="_eg_cl_dim">Built ' + _esc(String(man.builtAt || "").slice(0, 10)) + '</div>'
        : '<div class="_eg_cl_dim">No clause index yet. The drafting agent will generate every ' +
          'section from scratch until one is built.</div>';
      el.innerHTML =
        '<div class="_eg_manage_card_head">' +
          '<div class="_eg_manage_card_title"><span style="font-size:18px;">📚</span>' +
            '<span>Clause library</span></div>' +
          '<button id="_eg_cl_build" type="button" class="_eg_btn_secondary">' +
            (tpls.length ? 'Rebuild' : 'Build index') + '</button>' +
        '</div>' +
        '<div class="_eg_manage_card_desc">Indexes the services agreement, the NDA and the research agreement into ' +
          'reusable clauses, so drafts start from your own language.</div>' +
        status + listed;
      var btn = document.getElementById("_eg_cl_build");
      if (btn) btn.onclick = function () {
        btn.disabled = true; btn.textContent = "Indexing…";
        _clBuildIndex().then(function (r) {
          _renderClausePanel(r);
        }).catch(function (e) {
          el.innerHTML = '<div class="_eg_cl_warn">Indexing failed: ' + _esc(e && e.message) + '</div>';
        });
      };
    });
  }
  function _wireManageAgentsControls() {
    document.querySelectorAll("[data-eg-toggle-agent]").forEach(function (cb) {
      cb.onchange = function () {
        var id = cb.getAttribute("data-eg-toggle-agent");
        _getAgentSettings(id).then(function (s) {
          s.enabled = cb.checked;
          return _setAgentSettings(id, s);
        }).then(function () {
          _renderManageAgentsBody();  // refresh enabled-state label
        });
      };
    });
    document.querySelectorAll("[data-eg-tone]").forEach(function (sel) {
      sel.onchange = function () {
        var id = sel.getAttribute("data-eg-tone");
        _getAgentSettings(id).then(function (s) {
          s.tone = sel.value;
          return _setAgentSettings(id, s);
        });
      };
    });
  }
  function _closeManageAgentsModal() {
    var modal = document.getElementById("_eg_manage_modal");
    if (modal && modal.parentNode) modal.parentNode.removeChild(modal);
  }

  // ─── Bus listener: paint dropdown when ask_eli mounts its input ───
  // ask_eli emits 'ask_eli:input_mounted' (additive patch) with
  // { slotEl, sendBtn, inputEl, getQaContext }. We paint into slotEl
  // and mark the send button for label-flip. If ask_eli isn't
  // patched yet (older bundle), this listener simply never fires.
  // Bundle CSS is auto-injected by the kernel from style.css — no
  // manual injection needed.
  if (eli.bus && typeof eli.bus.on === "function") {
    eli.bus.on("ask_eli:input_mounted", function (payload) {
      _loadAutoRoute();
      _paintDropdown(payload);
    });
  }

  // ─── Dispatch handlers ────────────────────────────────────────────
  // intercept_submit: ask_eli calls this BEFORE running its Q&A
  // pipeline. If the current mode isn't "ask_eli", we open the agent
  // overlay and return { handled: true } to short-circuit ask_eli's
  // Q&A path. Returning falsy lets Q&A proceed normally.
  eli.register({
    eli_agent: {
      list_agents: function () { return _listAgents(); },
      get_agent_settings: function (agentId) { return _getAgentSettings(agentId); },
      set_agent_settings: function (payload) {
        if (!payload || !payload.agentId) return Promise.reject(new Error("Missing agentId"));
        return _setAgentSettings(payload.agentId, payload.settings || {});
      },
      intercept_submit: function (payload) {
        var text = (payload && payload.instruction) || "";
        // An explicitly chosen mode always wins — the dropdown is the
        // user saying what they want, and nothing should second-guess it.
        if (_currentMode && _currentMode !== "ask_eli") {
          _openAgentOverlay({
            agent: _currentMode.replace(/^agent:/, ""),
            instruction: text,
            qaIndex: payload && payload.qaIndex,
            docHash: payload && payload.docHash,
          });
          return { handled: true };
        }
        // Auto off — Ask ELI is untouched, synchronously, exactly as before.
        if (!_autoRoute) return { handled: false };
        // Auto on — read it first. Returns a promise; ask_eli awaits it.
        return _routeInstruction(text).then(function (route) {
          if (route !== "REVISE" && route !== "DRAFT") return { handled: false };
          _openAgentOverlay({
            // DRAFT writes something new; REVISE changes what is open. The
            // instruction becomes the drafter's intake seed either way.
            agent: route === "DRAFT" ? "draft_agreement" : "apply_instruction",
            instruction: text,
            qaIndex: payload && payload.qaIndex,
            docHash: payload && payload.docHash,
            routedAuto: true,
            routedTo: route,
          });
          return { handled: true };
        });
      },
      // Returns whether it opened, so a caller can tell "eli_agent is not
      // installed" (dispatch gives undefined) from "it opened" — an
      // unknown agent id returns ok:false rather than failing silently.
      open_agent: function (payload) {
        var p = payload || {};
        if (!_findAgent(p.agent)) return { ok: false, reason: "unknown agent: " + p.agent };
        _openAgentOverlay(p);
        return { ok: true };
      },
      get_current_mode: function () { return _currentMode; },
      set_mode: function (mode) { _setMode(mode); },
    },
    // Tile dispatch for users who pin the Manage Agents UI as a
    // standalone tile (audience controls keep this admin-only).
    tile: {
      app_eli_agent: function () {
        // 2026-05-17 v22: telemetry recording on tile launch.
        try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedEliAgent"); } catch (_) {}
        _openManageAgentsModal();
      },
    },
  });

  // ─── Helpers ──────────────────────────────────────────────────────
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  eli.log.event("tool", "eli_agent_initialized", { agentCount: AGENT_REGISTRY.length });
}

jsonTools.css:
/* tools/eli_agent/style.css
   ELI Agent — dropdown trigger, menu, agent overlay, Manage Agents
   modal. Light palette throughout (per CLAUDE.md theme split rule:
   tools + dialogs use light palette in both themes). */

/* ─── Inline caret next to ask_eli title ─── */
/* Sits between "🤖 Ask ELI" text and the index status dot. No
   button chrome — just a small chevron that reads as part of the
   title text. Clicking opens the mode menu. Tints amber when an
   agent mode is active so the user can see at a glance they're
   not in default Q&A mode. */
._eg_caret_inline {
  display: inline-block;
  margin: 0 6px 0 4px;
  font-size: 11px;
  color: currentColor;
  opacity: 0.55;
  cursor: pointer;
  user-select: none;
  vertical-align: middle;
  transition: opacity 0.12s, color 0.12s, transform 0.12s;
}
._eg_caret_inline:hover {
  opacity: 1;
  transform: translateY(1px);
}
._eg_caret_inline._eg_caret_active {
  color: #f59e0b;
  opacity: 1;
}

/* ─── Auto toggle (Step 0) ─────────────────────────────────────────────
 * Sits beside the Ask ELI title. OFF is the default and reads as off at
 * a glance — grey, knob left. ON takes the gold accent, because it is
 * the state where what you type may change the document. */
._eg_auto_toggle {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin: 0 2px 0 8px;
  cursor: pointer;
  user-select: none;
  vertical-align: middle;
}
._eg_auto_track {
  position: relative;
  display: inline-block;
  width: 24px;
  height: 13px;
  border-radius: 7px;
  background: rgba(148, 163, 184, .45);
  box-shadow: inset 0 0 0 1px rgba(100, 116, 139, .35);
  transition: background .14s ease, box-shadow .14s ease;
}
._eg_auto_knob {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 2px rgba(15, 23, 42, .35);
  transition: transform .14s ease;
}
._eg_auto_label {
  font: 700 9.5px/1.2 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: currentColor;
  opacity: .55;
  transition: opacity .14s ease, color .14s ease;
}
._eg_auto_toggle:hover ._eg_auto_label { opacity: .85; }
._eg_auto_on ._eg_auto_track {
  background: #c9a227;
  box-shadow: inset 0 0 0 1px #a1801c;
}
._eg_auto_on ._eg_auto_knob { transform: translateX(11px); }
._eg_auto_on ._eg_auto_label { opacity: 1; color: #c9a227; }

/* Shown in the agent panel when Auto routed the message here. */
._eg_routed {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin: -4px 0 0;
  padding: 7px 11px;
  background: #fffbeb;
  border: 1px solid #fcd34d;
  border-left: 3px solid #c9a227;
}
._eg_routed_text {
  font: 400 11px/1.45 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #78350f;
}
._eg_routed_btn {
  flex: 0 0 auto;
  padding: 3px 9px;
  border: 1px solid #d6bb62;
  border-radius: 2px;
  background: #fff;
  font: 700 10.5px/1.4 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #78350f;
  cursor: pointer;
  transition: background .12s, border-color .12s;
}
._eg_routed_btn:hover { background: #fef3c7; border-color: #c9a227; }

/* ─── Dropdown menu (floating below trigger) ─── */
._eg_menu_row {
  user-select: none;
  transition: background 0.08s;
}
._eg_menu_row:hover {
  background: #f1f5f9 !important;
}
._eg_menu_row_action {
  font-style: italic;
  color: #475569 !important;
}
._eg_menu_divider {
  height: 1px;
  background: #e2e8f0;
  margin: 4px 0;
}

/* ─── Agent overlay (the panel that opens on Plan Edits) ─── */
._eg_overlay {
  position: fixed;
  top: 80px;
  right: 24px;
  width: 480px;
  height: 520px;
  min-width: 360px;
  min-height: 320px;
  z-index: 99998;
  background: #fff;
  border: 1px solid #cbd5e1;
  box-shadow: 0 16px 48px rgba(15, 23, 42, 0.32);
  font-family: Inter, 'Segoe UI', system-ui, sans-serif;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
._eg_header {
  padding: 11px 14px;
  background: linear-gradient(135deg, #1e3a8a 0%, #1565c0 100%);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  cursor: move;
  user-select: none;
  flex: 0 0 auto;
}
._eg_header_title {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
._eg_header_icon {
  font-size: 16px;
  line-height: 1;
}
._eg_header_label {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.02em;
}
._eg_header_actions {
  display: flex;
  gap: 4px;
}
._eg_btn_ghost {
  background: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.4);
  color: #fff;
  padding: 3px 9px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  border-radius: 0;
  line-height: 1.2;
  transition: background 0.12s;
}
._eg_btn_ghost:hover {
  background: rgba(255, 255, 255, 0.28);
}
._eg_body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  color: #0f172a;
}
._eg_section_label {
  font: 700 9px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #64748b;
}
._eg_instruction {
  padding: 10px 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #1565c0;
  font-size: 13px;
  line-height: 1.5;
  color: #0f172a;
  white-space: pre-wrap;
}
._eg_context {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 12px;
  background: #fff;
  border: 1px solid #e2e8f0;
  font-family: monospace;
  font-size: 11px;
  color: #475569;
}
._eg_status_box {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: #fef3c7;
  border: 1px solid #fcd34d;
  font-size: 11px;
  color: #92400e;
  font-weight: 600;
}
._eg_status_dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #f59e0b;
  flex-shrink: 0;
  animation: _eg_pulse 1.6s ease-in-out infinite;
}
@keyframes _eg_pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.45; }
}

/* ─── Review UI: summary, stats, edit cards, diff styling ─── */
._eg_summary {
  font-size: 12px;
  line-height: 1.55;
  color: #0f172a;
  padding: 10px 12px;
  background: #f1f5f9;
  border-left: 3px solid #1565c0;
}
._eg_review_stats {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  font-size: 10px;
}
._eg_stat {
  padding: 3px 8px;
  font-weight: 700;
  background: #fff;
  border: 1px solid #cbd5e1;
  color: #475569;
}
._eg_stat_rejected { background: #fee2e2; border-color: #fca5a5; color: #991b1b; }
._eg_stat_pending  { background: #fef3c7; border-color: #fcd34d; color: #92400e; }

._eg_group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
._eg_group_header {
  font: 700 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #1e3a8a;
  padding: 6px 0 4px;
  border-bottom: 1px solid #cbd5e1;
}
._eg_group_count {
  color: #64748b;
  font-weight: 500;
}

._eg_card {
  background: #fff;
  border: 1px solid #cbd5e1;
  border-left: 3px solid #cbd5e1;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: border-color 0.12s, background 0.12s;
}
._eg_card_accepted { border-left-color: #10b981; background: #f0fdf4; }
._eg_card_rejected { border-left-color: #ef4444; background: #fef2f2; opacity: 0.6; }
._eg_card_pending  { border-left-color: #f59e0b; }
._eg_card_review   { border-left-color: #d97706; background: #fffbeb; }

._eg_card_top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}
._eg_card_meta {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  color: #475569;
  flex-wrap: wrap;
}
._eg_type_badge {
  font: 700 9px/1.2 monospace;
  padding: 2px 5px;
  border-radius: 2px;
  letter-spacing: 0.5px;
  white-space: nowrap;   /* "NEW SECTION" must not break across two lines */
}
._eg_type_replace { background: #dbeafe; color: #1e3a8a; }
._eg_type_insert  { background: #d1fae5; color: #065f46; }
._eg_type_delete  { background: #fee2e2; color: #991b1b; }
._eg_card_section {
  font-weight: 600;
  color: #0f172a;
}
._eg_card_category {
  font-family: monospace;
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  padding: 2px 6px;
  color: #475569;
  border-radius: 2px;
}
/* Location header — section title + paragraph index — at the top of
   each card so the user knows WHERE in the doc the edit lands before
   reading the diff. */
._eg_card_loc {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 4px 8px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #1565c0;
  margin-bottom: 2px;
}
._eg_card_loc_section {
  font-size: 11px;
  font-weight: 700;
  color: #0f172a;
  line-height: 1.3;
}
._eg_card_loc_unknown {
  color: #94a3b8;
  font-weight: 500;
  font-style: italic;
}
._eg_card_loc_para {
  font-size: 10px;
  color: #64748b;
  font-family: monospace;
  line-height: 1.3;
}
._eg_card_dots {
  font-family: monospace;
  font-size: 11px;
  color: #1565c0;
  letter-spacing: -1px;
}
._eg_card_review_pill {
  font: 700 9px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  background: #fef3c7;
  color: #92400e;
  padding: 2px 6px;
  border-radius: 2px;
}

._eg_card_diff {
  font-family: Georgia, serif;
  font-size: 12px;
  line-height: 1.5;
  color: #0f172a;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
._eg_diff_orig {
  background: #fee2e2;
  padding: 6px 8px;
  border-left: 2px solid #ef4444;
}
._eg_diff_orig del {
  color: #991b1b;
  text-decoration: line-through;
}
._eg_diff_orig._eg_diff_insert_anchor {
  background: #f1f5f9;
  border-left-color: #94a3b8;
  font-size: 10px;
  font-style: italic;
  color: #475569;
  font-family: 'Inter', sans-serif;
}
._eg_diff_new {
  background: #d1fae5;
  padding: 6px 8px;
  border-left: 2px solid #10b981;
}
._eg_diff_new ins {
  color: #065f46;
  text-decoration: none;
  font-weight: 600;
}

._eg_card_rationale {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 9px;
  padding-top: 8px;
  border-top: 1px solid #eef2f7;
}
/* Gold, because this is the one piece of the card that is an argument
   rather than a fact — and gold is the project's single accent. */
._eg_card_why {
  flex: 0 0 auto;
  padding: 2px 8px;
  border: 1px solid #e8d89a;
  border-radius: 9px;
  background: linear-gradient(180deg, #fffdf5, #fbf3dc);
  font: 800 8.5px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #8a6d16;
  white-space: nowrap;
}
._eg_card_why_text {
  font-size: 11px;
  line-height: 1.5;
  color: #475569;
}
._eg_card_actions {
  display: flex;
  gap: 7px;
  flex-wrap: wrap;
  margin-top: 10px;
  padding-top: 9px;
  border-top: 1px solid #eef2f7;
  /* Clicking the card scrolls this row into view. The chat's input bar
     floats over the bottom of the transcript, so without this the buttons
     land behind it and you have to scroll again to reach them. */
  scroll-margin-bottom: 132px;
}
._eg_card_btn {
  font: 700 9.5px/1 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .07em;
  text-transform: uppercase;
  min-width: 68px;
  padding: 7px 13px;
  border: 1px solid #cbd5e1;
  background: linear-gradient(180deg, #fff, #f6f8fb);
  color: #0f172a;
  cursor: pointer;
  border-radius: 2px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, .06);
  transition: background .14s, border-color .14s, box-shadow .14s, transform .14s;
}
._eg_card_btn:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 3px 8px rgba(15, 23, 42, .12);
}
._eg_card_btn:active:not(:disabled) {
  transform: none;
  box-shadow: inset 0 1px 2px rgba(15, 23, 42, .14);
}
._eg_card_btn:hover:not(:disabled) {
  background: #f1f5f9;
  border-color: #94a3b8;
}
._eg_card_btn:disabled {
  opacity: 0.5;
  cursor: default;
}
/* Apply and Reject, in one blue family. Apply is filled and Reject is
   outlined in the same hue: the pair reads as a single decision rather
   than an action and a warning, and neither is dressed as a
   recommendation — the card is not making one. Weight, not colour, is
   what separates them. */
._eg_card_apply1 {
  background: linear-gradient(180deg, #2f6fdd, #1d4fb0);
  border-color: #1a4699;
  color: #fff;
  font-weight: 700;
  box-shadow: 0 1px 2px rgba(23, 60, 130, .28);
}
._eg_card_apply1:hover:not(:disabled) {
  background: linear-gradient(180deg, #3d7ee8, #1f57c0);
  border-color: #17408c;
  color: #fff;
  box-shadow: 0 3px 8px rgba(23, 60, 130, .32);
}
._eg_card_reject {
  background: linear-gradient(180deg, #fff, #f4f7fc);
  border-color: #9db6e0;
  color: #1d4fb0;
  font-weight: 600;
}
._eg_card_reject:hover:not(:disabled) {
  background: linear-gradient(180deg, #fff, #e8eefb);
  border-color: #6d92d4;
  color: #17408c;
}
/* Rejected stays clickable — pressing it again restores the edit. */
._eg_card_rejected_on {
  background: #fee2e2;
  border-color: #ef4444;
  color: #991b1b;
}
/* The rejected STATE stays red — that is a status, not an action, and it
   has to survive the blue hover rule above, which is more specific. */
._eg_card_reject._eg_card_rejected_on:hover:not(:disabled) {
  background: #fecaca;
  border-color: #dc2626;
  color: #7f1d1d;
}
/* Sticky bottom action row in the review view. */
._eg_actions_row {
  display: flex;
  gap: 8px;
  padding: 10px 0 4px;
  flex-wrap: wrap;
  align-items: center;
}
._eg_actions_sticky {
  position: sticky;
  bottom: -16px;
  margin: 4px -16px -16px;
  padding: 12px 16px;
  background: #fff;
  border-top: 1px solid #cbd5e1;
  z-index: 5;
}
._eg_btn_primary {
  font: 700 11px/1.2 'Inter', sans-serif;
  padding: 7px 14px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  cursor: pointer;
  border-radius: 0;
  transition: transform 0.12s, box-shadow 0.12s;
}
._eg_btn_primary:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 3px 10px rgba(21,101,192,0.28);
}
._eg_btn_primary:disabled { opacity: 0.5; cursor: default; }
._eg_btn_apply {
  margin-left: auto;
}
._eg_btn_secondary {
  font: 600 10px/1.2 'Inter', sans-serif;
  padding: 6px 12px;
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border: 1px solid #cbd5e1;
  color: #0f172a;
  cursor: pointer;
  border-radius: 0;
}
._eg_btn_secondary:hover { background: linear-gradient(180deg, #f1f5f9 0%, #cbd5e1 100%); }

/* Empty / error / applied states. */
._eg_empty_box {
  padding: 24px;
  text-align: center;
  background: #f8fafc;
  border: 1px dashed #cbd5e1;
}
._eg_empty_title {
  font-size: 13px;
  font-weight: 700;
  color: #0f172a;
  margin-bottom: 6px;
}
._eg_empty_msg {
  font-size: 11px;
  color: #64748b;
  line-height: 1.5;
}
._eg_error_box {
  padding: 14px 16px;
  background: #fef2f2;
  border: 1px solid #fca5a5;
  border-left: 3px solid #ef4444;
}
._eg_error_title {
  font-size: 12px;
  font-weight: 700;
  color: #991b1b;
  margin-bottom: 4px;
}
._eg_error_msg {
  font-size: 11px;
  color: #7f1d1d;
  line-height: 1.5;
  word-wrap: break-word;
}
._eg_applied_box {
  padding: 14px 16px;
  background: #d1fae5;
  border: 1px solid #6ee7b7;
  border-left: 3px solid #10b981;
}
._eg_applied_title {
  font-size: 13px;
  font-weight: 800;
  color: #065f46;
  margin-bottom: 4px;
}
._eg_applied_sub {
  font-size: 11px;
  color: #047857;
  line-height: 1.5;
}
._eg_fail_card {
  padding: 10px 12px;
  background: #fef2f2;
  border: 1px solid #fecaca;
  border-left: 3px solid #ef4444;
  margin-bottom: 8px;
}
._eg_fail_card._eg_card_clickloc:hover {
  background: #fee2e2;
  border-color: #ef4444;
}
._eg_fail_head {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 5px;
}
._eg_fail_badge {
  flex: 0 0 auto;
  padding: 2px 7px;
  background: #fee2e2;
  border: 1px solid #fca5a5;
  border-radius: 2px;
  font: 800 8.5px/1.4 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: #991b1b;
  white-space: nowrap;
}
._eg_fail_where {
  font-size: 10px;
  color: #9f6b6b;
  font-family: monospace;
}
/* What it WOULD have changed. Without this there is nothing to act on. */
._eg_fail_ba {
  margin: 7px 0 0;
  padding: 7px 0 0;
  border-top: 1px dashed #fecaca;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
._eg_fail_row {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
._eg_fail_tag {
  flex: 0 0 62px;
  font: 800 8.5px/1.6 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: #9f6b6b;
}
._eg_fail_tag_new { color: #065f46; }
._eg_fail_tag_del { color: #991b1b; }
._eg_fail_val {
  flex: 1 1 auto;
  min-width: 0;
  font-family: Georgia, serif;
  font-size: 11.5px;
  line-height: 1.5;
  color: #0f172a;
  word-wrap: break-word;
}
._eg_fail_why {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 7px;
}
/* The same note on a review card, when a single Apply failed. It used to be
   recorded and never rendered — the card just stayed pending. */
._eg_card_fail {
  margin-top: 8px;
  padding: 7px 9px;
  background: #fef2f2;
  border-left: 3px solid #ef4444;
  font-size: 11px;
  line-height: 1.45;
  color: #7f1d1d;
}
._eg_card_fail_tag {
  display: inline-block;
  margin-right: 6px;
  font: 800 8.5px/1.4 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: #991b1b;
}
/* Applied-edit summary rows on the final page. The row itself locates. */
._eg_applied_row {
  display: grid;
  grid-template-columns: 1fr;
  gap: 6px;
  padding: 8px 10px;
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
  border-left: 3px solid #10b981;
  margin-bottom: 6px;
  align-items: center;
}
/* Stay in the green family on hover — the shared clickloc hover goes slate,
   which reads as a different kind of row. */
._eg_applied_row._eg_card_clickloc:hover {
  background: #ecfdf5;
  border-color: #10b981;
}
._eg_applied_meta {
  grid-column: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  color: #475569;
}
._eg_applied_para {
  font-family: monospace;
  color: #64748b;
}
._eg_applied_change {
  grid-column: 1;
  font-family: Georgia, serif;
  font-size: 12px;
  line-height: 1.5;
  color: #0f172a;
  word-wrap: break-word;
}
._eg_applied_inserts {
  color: #065f46;
  font-weight: 600;
}
._eg_fail_reason {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #991b1b;
  margin-bottom: 4px;
}

/* ─── Stage strip (5-stage pipeline progress) ─── */
/* Eight stages do not fit one line in a narrow pane — wrap rather than
 * squeeze the separators to nothing. */
._eg_stage_strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
  padding: 8px 0 4px;
  margin-bottom: 4px;
}
._eg_stage_dot {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 0 0 auto;
}
._eg_stage_pip {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #e2e8f0;
  border: 1px solid #cbd5e1;
}
._eg_stage_done ._eg_stage_pip {
  background: #10b981;
  border-color: #059669;
}
._eg_stage_active ._eg_stage_pip {
  background: #f59e0b;
  border-color: #d97706;
  animation: _eg_pulse 1.6s ease-in-out infinite;
}
._eg_stage_label {
  font: 600 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #94a3b8;
}
._eg_stage_done ._eg_stage_label  { color: #065f46; }
._eg_stage_active ._eg_stage_label { color: #92400e; font-weight: 700; }
._eg_stage_sep {
  flex: 1 1 auto;
  min-width: 6px;
  height: 1px;
  background: #e2e8f0;
}
/* The strip's nine labels are 9px and wrap on a narrow pane, so which one
   is lit is easy to miss. This says it in words. */
._eg_stage_step {
  font: 700 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #92400e;
  padding-bottom: 6px;
  border-bottom: 1px solid #e2e8f0;
  margin-bottom: 8px;
}

/* ─── Buckets list (Stage 3 progress) ─── */
._eg_bucket_list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
._eg_bucket_row {
  display: grid;
  grid-template-columns: 24px 1fr auto;
  grid-template-rows: auto auto;
  gap: 2px 8px;
  padding: 8px 10px;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-left: 3px solid #cbd5e1;
  font-size: 11px;
  align-items: center;
}
._eg_bucket_running,
._eg_bucket_drafting { border-left-color: #f59e0b; background: #fffbeb; }
._eg_bucket_done    { border-left-color: #10b981; background: #f0fdf4; }
._eg_bucket_failed  { border-left-color: #ef4444; background: #fef2f2; }
/* Not started yet. Held back rather than given a fourth colour, so the
   eye goes to the three that are actually running. */
._eg_bucket_queued  { opacity: 0.55; }
._eg_bucket_icon {
  grid-row: 1 / 3;
  text-align: center;
  font-size: 14px;
  font-weight: 700;
  color: #475569;
}
._eg_bucket_running ._eg_bucket_icon,
._eg_bucket_drafting ._eg_bucket_icon {
  color: #d97706;
  animation: _eg_pulse 1.4s ease-in-out infinite;
}
._eg_bucket_done ._eg_bucket_icon   { color: #059669; }
._eg_bucket_failed ._eg_bucket_icon { color: #dc2626; }
._eg_bucket_name {
  grid-column: 2;
  grid-row: 1;
  font-weight: 700;
  color: #0f172a;
}
._eg_bucket_focus {
  grid-column: 2;
  grid-row: 2;
  color: #64748b;
  font-size: 10px;
  line-height: 1.4;
}
._eg_bucket_count {
  grid-column: 3;
  grid-row: 1 / 3;
  font: 700 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #475569;
  white-space: nowrap;
  text-align: right;
}
/* How far through the outline the drafter is. The count in the label says
   the same thing, but a number that changes every twenty seconds does not
   read as movement and a bar does. */
._eg_dr_bar {
  height: 3px;
  background: #e2e8f0;
  margin: 0 0 6px;
  overflow: hidden;
}
._eg_dr_bar > span {
  display: block;
  height: 100%;
  background: #10b981;
  transition: width 0.4s ease;
}

/* ─── Unrequested findings panel (collapsible) ─── */
._eg_un_panel {
  background: #fff;
  border: 1px solid #d97706;
  border-left: 4px solid #d97706;
  margin: 8px 0;
}
._eg_un_summary {
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 10px 12px;
  background: #fffbeb;
  cursor: pointer;
  color: #92400e;
  user-select: none;
}
._eg_un_panel[open] ._eg_un_summary { border-bottom: 1px solid #cbd5e1; }
._eg_un_card {
  padding: 10px 12px;
  border-bottom: 1px solid #f1f5f9;
}
._eg_un_card:last-child { border-bottom: none; }
._eg_un_high { background: #fef2f2; }
._eg_un_med  { background: #fffbeb; }
._eg_un_low  { background: #f8fafc; }
._eg_un_head {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-bottom: 4px;
}
._eg_un_sev {
  font: 700 9px/1.2 monospace;
  letter-spacing: 0.4px;
  padding: 2px 6px;
  background: #fff;
  border: 1px solid #cbd5e1;
  color: #475569;
}
._eg_un_high ._eg_un_sev { color: #991b1b; border-color: #fca5a5; }
._eg_un_low ._eg_un_sev  { color: #64748b; }
._eg_un_section {
  font-weight: 600;
  font-size: 11px;
  color: #0f172a;
}
._eg_un_observation {
  font-size: 12px;
  line-height: 1.5;
  color: #0f172a;
  margin-bottom: 4px;
}
._eg_un_action {
  font-size: 11px;
  color: #475569;
  font-style: italic;
}

/* ─── Mini-map sidebar (right edge of review) ─── */
._eg_review_main {
  display: flex;
  gap: 8px;
}
._eg_cards_col {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
}
._eg_minimap {
  flex: 0 0 18px;
  position: relative;
}
._eg_mm_track {
  position: sticky;
  top: 8px;
  width: 18px;
  height: calc(100vh - 220px);
  min-height: 200px;
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
  border-radius: 9px;
}
._eg_mm_pin {
  position: absolute;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1px solid #475569;
  background: #94a3b8;
  cursor: pointer;
  padding: 0;
  transition: transform 0.1s, box-shadow 0.1s;
}
._eg_mm_pin:hover {
  transform: translate(-50%, -50%) scale(1.4);
  box-shadow: 0 0 0 3px rgba(245,158,11,0.3);
}
._eg_mm_accepted { background: #10b981; border-color: #065f46; }
._eg_mm_rejected { background: #ef4444; border-color: #991b1b; opacity: 0.5; }
._eg_mm_pending  { background: #f59e0b; border-color: #d97706; }
._eg_mm_review { box-shadow: 0 0 0 2px #fcd34d; }

/* ─── Inline redline (Word-style) ─── */
._eg_inline_diff {
  background: #fff;
  padding: 10px 12px;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #1565c0;
  font-family: Georgia, serif;
  font-size: 12px;
  line-height: 1.6;
  color: #0f172a;
  word-wrap: break-word;
}
._eg_inline_del {
  color: #991b1b;
  text-decoration: line-through;
  text-decoration-color: #ef4444;
  background: #fee2e2;
  padding: 0 2px;
}
._eg_inline_ins {
  color: #065f46;
  background: #d1fae5;
  text-decoration: underline;
  text-decoration-color: #10b981;
  font-weight: 600;
  padding: 0 2px;
  margin-left: 2px;
}


/* ─── Card flash (mini-map + strategy pill scroll target) ─── */
@keyframes _eg_flash_anim {
  0%   { background: #fef3c7; box-shadow: 0 0 0 4px #f59e0b; }
  100% { background: transparent; box-shadow: none; }
}
._eg_card_flash {
  animation: _eg_flash_anim 1.4s ease-out;
}

/* ─── Email-to-Redline: compose pane + confirm + response email ─── */
._eg_compose_hint {
  font-size: 11px;
  color: #475569;
  line-height: 1.5;
  padding: 4px 0 8px;
}
._eg_compose_method {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #1565c0;
}
._eg_compose_method_head {
  font: 700 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #475569;
}
._eg_compose_meta {
  font-size: 11px;
  color: #64748b;
  margin-left: 8px;
}
._eg_compose_textarea {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid #cbd5e1;
  font-family: monospace;
  font-size: 11px;
  line-height: 1.5;
  background: #fff;
  color: #0f172a;
  resize: vertical;
  min-height: 100px;
  border-radius: 0;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}
._eg_compose_textarea:focus {
  border-color: #1565c0;
  box-shadow: 0 0 0 2px rgba(21,101,192,0.18);
}
._eg_drop_zone {
  border: 2px dashed #cbd5e1;
  background: #fff;
  padding: 18px 12px;
  text-align: center;
  font-size: 11px;
  color: #64748b;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}
._eg_drop_zone._eg_drop_active {
  border-color: #1565c0;
  background: #eff6ff;
  color: #1e3a8a;
}
._eg_link_btn {
  background: none;
  border: none;
  color: #1565c0;
  text-decoration: underline;
  cursor: pointer;
  font: inherit;
  padding: 0;
}
._eg_comment_row {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 12px;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-left: 3px solid #1565c0;
  margin-bottom: 6px;
}
._eg_comment_skipped {
  opacity: 0.55;
  border-left-color: #94a3b8;
}
._eg_comment_head {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 10px;
  color: #475569;
}
._eg_comment_toggle {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-weight: 700;
  cursor: pointer;
  user-select: none;
}
._eg_comment_sev {
  font: 700 9px/1.2 monospace;
  letter-spacing: 0.4px;
  padding: 2px 6px;
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
}
._eg_comment_sev_high     { background: #fee2e2; border-color: #fca5a5; color: #991b1b; }
._eg_comment_sev_must-fix { background: #fee2e2; border-color: #fca5a5; color: #991b1b; }
._eg_comment_sev_med      { background: #fef3c7; border-color: #fcd34d; color: #92400e; }
._eg_comment_sev_low      { background: #f1f5f9; color: #64748b; }
._eg_comment_sev_nit      { background: #f1f5f9; color: #64748b; }
._eg_comment_author {
  font-weight: 700;
  color: #0f172a;
}
._eg_comment_scope {
  color: #1e3a8a;
  font-weight: 600;
}
._eg_comment_ask {
  font-size: 12px;
  line-height: 1.5;
  color: #0f172a;
}
._eg_comment_orig {
  font-size: 10px;
  color: #475569;
  background: #f8fafc;
  padding: 0;
  border: 1px dashed #e2e8f0;
}
._eg_comment_orig summary {
  padding: 4px 8px;
  cursor: pointer;
  user-select: none;
  font-weight: 600;
}
._eg_comment_orig div {
  padding: 6px 8px;
  font-style: italic;
  border-top: 1px dashed #e2e8f0;
}
/* Comment-link pill on edit cards (email-agent provenance trace) */
._eg_card_comment_link {
  font-size: 10px;
  color: #1e3a8a;
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  padding: 4px 8px;
  border-radius: 2px;
  font-style: italic;
  line-height: 1.4;
  cursor: help;
}

/* ─── Draft Document: interview pane ─── */
._eg_iv_thread {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 8px;
}
._eg_iv_turn {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 12px;
  border-radius: 2px;
}
._eg_iv_user {
  background: #eff6ff;
  border-left: 3px solid #1565c0;
  align-self: flex-end;
  max-width: 88%;
}
._eg_iv_agent {
  background: #f8fafc;
  border-left: 3px solid #94a3b8;
  align-self: flex-start;
  max-width: 88%;
}
._eg_iv_role {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #64748b;
}
._eg_iv_text {
  font-size: 12px;
  line-height: 1.5;
  color: #0f172a;
  white-space: pre-wrap;
}
/* What a screen wants from you — the outline to approve, the sections to
   review, the last check before anything is written. Scrolled to when the
   screen opens, with room above so it does not land flush under whatever
   the transcript has floating at the top. */
#_eg_gate {
  scroll-margin-top: 12px;
}

/* ─── The full draft, as it will be inserted ───────────────────────────
   Set like the document rather than like the panel: Times New Roman at
   the same 11pt the insert applies, centred title and headings, real
   indents. Reading it should answer "is this a document", which a column
   of review cards never does. */
._eg_dp_meta {
  font: 600 10px/1.3 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #64748b;
  padding-bottom: 8px;
  border-bottom: 1px solid #e2e8f0;
  margin-bottom: 14px;
}
._eg_dp_page {
  background: #fff;
  padding: 4px 2px 8px;
}
._eg_dp_p {
  font-family: 'Times New Roman', Times, serif;
  font-size: 13px;
  line-height: 1.55;
  color: #0f172a;
  margin: 0 0 8px;
}
._eg_dp_title {
  text-align: center;
  font-size: 15px;
  font-weight: 700;
  margin: 4px 0 16px;
}
._eg_dp_heading {
  text-align: center;
  font-weight: 700;
  margin: 14px 0 6px;
}
/* A memo's or policy's heading is ranged left, exactly as the insert
   sets it. */
._eg_dp_subhead {
  font-weight: 700;
  margin: 14px 0 4px;
}
._eg_dp_reline { font-weight: 700; margin: 12px 0; }
._eg_dp_partyname { font-weight: 700; margin: 18px 0 2px; }
._eg_dp_sigline { margin: 0 0 2px; color: #334155; }
._eg_dp_num {
  font-weight: 700;
  margin-right: 8px;
}
/* Anything still to fill in. The follow-up lists these too, but seeing
   them in place is what tells you whether they matter. */
._eg_dp_ph {
  background: #fef3c7;
  color: #92400e;
  font-weight: 700;
  padding: 0 2px;
  border-radius: 2px;
}
._eg_dp_empty {
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #64748b;
  padding: 20px 0;
  text-align: center;
}

/* The end of the thread: the newest question and the box to answer it, or
   Generate Draft. Scrolled to after every turn. */
#_eg_iv_tail {
  /* Same reason as _eg_card_actions: the chat's input bar floats over the
     bottom of the transcript, so without this the button lands behind it
     and you have to scroll again to reach it. */
  scroll-margin-bottom: 132px;
  padding-bottom: 28px;
}
/* In the interview the action row is the end of a conversation, not a
   toolbar pinned to the panel edge — it sits after the last bubble, with
   room under it. */
#_eg_iv_tail ._eg_actions_sticky {
  position: static;
  margin: 8px 0 0;
  padding: 0;
  border-top: none;
  background: transparent;
}

/* Between an answer and the next question there is an AI call. Without
   this the pane rendered nothing at all and the thread looked finished. */
._eg_iv_thinking ._eg_iv_text {
  display: inline-flex;
  align-items: center;
  color: #64748b;
  font-style: italic;
}
._eg_iv_choices {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 8px 0;
}
._eg_iv_choice_btn {
  flex: 0 0 auto;
}
._eg_iv_input_row {
  display: flex;
  gap: 6px;
  padding: 6px 0;
}
._eg_iv_text_input {
  flex: 1 1 auto;
  padding: 8px 10px;
  border: 1px solid #cbd5e1;
  font-size: 12px;
  font-family: inherit;
  background: #fff;
  color: #0f172a;
  border-radius: 0;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}
._eg_iv_text_input:focus {
  border-color: #1565c0;
  box-shadow: 0 0 0 2px rgba(21,101,192,0.18);
}

/* Draft outline review */
._eg_outline_row {
  display: flex;
  gap: 12px;
  padding: 10px 12px;
  background: #fff;
  border: 1px solid #cbd5e1;
  border-left: 3px solid #1565c0;
  margin-bottom: 4px;
  align-items: flex-start;
}
._eg_outline_num {
  font: 700 13px/1.2 monospace;
  color: #1e3a8a;
  flex-shrink: 0;
  width: 36px;
}
._eg_outline_name {
  font-weight: 700;
  color: #0f172a;
  font-size: 12px;
}
._eg_outline_focus {
  font-size: 10px;
  color: #64748b;
  line-height: 1.4;
  margin-top: 2px;
}

/* Draft section review cards */
._eg_draft_section {
  background: #fff;
  border: 1px solid #cbd5e1;
  border-left: 3px solid #10b981;
  margin-bottom: 10px;
}
._eg_draft_section_skip {
  border-left-color: #ef4444;
  opacity: 0.55;
}
._eg_draft_section_head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: #f8fafc;
  border-bottom: 1px solid #e2e8f0;
}
._eg_draft_section_title {
  font-weight: 700;
  color: #0f172a;
  font-size: 12px;
}
._eg_draft_section_actions {
  display: flex;
  gap: 4px;
}
._eg_draft_regen {
  background: #fef3c7;
  color: #92400e;
  border-color: #fcd34d;
}
._eg_draft_preview {
  margin: 0;
  padding: 12px 14px;
  font-family: Georgia, serif;
  font-size: 12px;
  line-height: 1.6;
  color: #0f172a;
  white-space: pre-wrap;
  max-height: 320px;
  overflow-y: auto;
  background: #fff;
}

/* ─── Manage Agents modal ─── */
._eg_modal_backdrop {
  position: fixed;
  inset: 0;
  z-index: 99999;
  background: rgba(15, 23, 42, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: Inter, 'Segoe UI', system-ui, sans-serif;
}
._eg_modal_panel {
  background: #fff;
  width: min(640px, 92vw);
  max-height: min(720px, 88vh);
  display: flex;
  flex-direction: column;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.4);
  border: 1px solid #cbd5e1;
  overflow: hidden;
}
._eg_modal_header {
  padding: 11px 14px;
  background: linear-gradient(135deg, #1e3a8a 0%, #1565c0 100%);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex: 0 0 auto;
}
._eg_modal_title {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.02em;
}
._eg_modal_body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: #f8fafc;
}
._eg_manage_card {
  background: #fff;
  border: 1px solid #cbd5e1;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
._eg_manage_card_head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
._eg_manage_card_title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  font-weight: 700;
  color: #0f172a;
}
._eg_manage_card_desc {
  font-size: 11px;
  color: #475569;
  line-height: 1.5;
}
._eg_manage_card_settings {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 8px;
  border-top: 1px dashed #e2e8f0;
}
._eg_setting_label {
  font: 600 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #64748b;
}
._eg_manage_card_settings select {
  padding: 5px 8px;
  font-size: 11px;
  font-family: inherit;
  border: 1px solid #cbd5e1;
  background: #fff;
  border-radius: 0;
  cursor: pointer;
  color: #0f172a;
}
._eg_toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 600;
  color: #475569;
  cursor: pointer;
  user-select: none;
}
._eg_toggle input[type="checkbox"] {
  cursor: pointer;
  margin: 0;
}

/* ─── Verification panel (deterministic coherence check) ───────────────
 * Consequences of the edit SET, shown above the cards. Amber, not red:
 * these are things to decide about, not errors. The clean state is
 * deliberately visible too — silence would be ambiguous. */
._eg_verify_box {
  margin: 10px 0;
  padding: 10px 12px;
  background: #fffbeb;
  border: 1px solid #fcd34d;
  border-left: 3px solid #d97706;
}
._eg_verify_title {
  font: 800 10px/1.2 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .09em;
  text-transform: uppercase;
  color: #92400e;
  margin-bottom: 6px;
}
._eg_verify_row {
  font: 400 11.5px/1.55 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #78350f;
  margin-top: 4px;
}
._eg_verify_row b { font-weight: 700; }
._eg_verify_ok {
  margin: 10px 0;
  padding: 7px 11px;
  background: #ecfdf5;
  border: 1px solid #a7f3d0;
  font: 600 11px/1.4 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #065f46;
}

/* ─── In-chat panel ────────────────────────────────────────────────────
 * The agent lives in Ask ELI's transcript, so it has to read as part of
 * the conversation rather than a window that landed in it: no shadow, no
 * floating chrome, full width, and the body scrolls with the chat instead
 * of trapping a scrollbar inside a bubble. */
._eg_body_chat {
  max-height: none;
  overflow: visible;
  padding: 14px;
  gap: 12px;
  background: #fff;
}
._eg_body_chat ._eg_actions_sticky {
  position: static;
  box-shadow: none;
}

/* ─── Clarify checkpoint ───────────────────────────────────────────────
 * Questions asked before any drafting. This is the one screen that asks
 * the user for something, so it gets the most care: generous spacing, a
 * numbered rail, and an input that looks like it wants to be typed in. */
._eg_clar_row {
  position: relative;
  margin: 10px 0;
  padding: 13px 15px 13px 42px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 3px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, .04);
}
._eg_clar_q {
  font: 600 13px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #0f172a;
  letter-spacing: -0.01em;
}
._eg_clar_n {
  position: absolute;
  left: 13px;
  top: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 19px;
  height: 19px;
  border-radius: 50%;
  background: #0f172a;
  color: #fff;
  font: 800 10px/1 Inter, 'Segoe UI', system-ui, sans-serif;
}
._eg_clar_why {
  margin: 4px 0 0;
  font: 400 11.5px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #64748b;
}
._eg_clar_opts {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin: 9px 0 0;
}
._eg_clar_opt {
  padding: 4px 11px;
  border: 1px solid #cbd5e1;
  border-radius: 13px;
  background: #fff;
  font: 600 11px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #334155;
  cursor: pointer;
  transition: border-color .12s, background .12s, color .12s;
}
._eg_clar_opt:hover {
  border-color: #c9a227;
  background: #fffbeb;
  color: #78350f;
}
._eg_clar_input {
  width: 100%;
  margin: 9px 0 0;
  padding: 8px 11px;
  border: 1px solid #cbd5e1;
  border-radius: 3px;
  background: #fff;
  font: 400 12.5px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #0f172a;
  box-sizing: border-box;
  transition: border-color .12s, box-shadow .12s;
}
._eg_clar_input:focus {
  outline: none;
  border-color: #c9a227;
  box-shadow: 0 0 0 3px rgba(201, 162, 39, .14);
}
._eg_clar_input::placeholder { color: #94a3b8; }

/* Recap in the review — what was asked, and what was assumed when it
 * wasn't answered. An assumption has to stay visible next to the edits
 * it shaped. */
._eg_clar_recap {
  margin: 10px 0;
  padding: 8px 11px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
}
._eg_clar_recap_head {
  font: 800 10px/1.2 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .09em;
  text-transform: uppercase;
  color: #64748b;
  margin-bottom: 5px;
}
._eg_clar_recap_row {
  font: 400 11.5px/1.55 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #475569;
  margin-top: 3px;
}
._eg_clar_ans { font-weight: 700; color: #0f172a; }
._eg_clar_assumed {
  font-weight: 600;
  font-style: italic;
  color: #b45309;
}

/* ─── Activity stream ──────────────────────────────────────────────────
 * A timeline, not a log file: one rail, a dot per step, the step in
 * sentence case and its detail beneath in muted grey. Rows arrive one at
 * a time and slide in, so a burst of twelve reads as work happening.
 * Three colours only — navy for structure, green for found/done, amber
 * for anything that wants a second look. */
._eg_st_panel {
  margin: 8px 0;
  border: 1px solid #e2e8f0;
  border-radius: 3px;
  background: #fff;
  overflow: hidden;
}
._eg_st_summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 9px 12px;
  cursor: pointer;
  user-select: none;
  list-style: none;
}
._eg_st_summary::-webkit-details-marker { display: none; }
._eg_st_sum_label {
  font: 800 9.5px/1.2 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #64748b;
}
._eg_st_sum_count {
  min-width: 18px;
  padding: 1px 7px;
  border-radius: 9px;
  background: #f1f5f9;
  font: 800 10px/1.6 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #475569;
  text-align: center;
}
/* While it is running the count wears the accent, so a glance at the
   collapsed panel tells you whether anything is still happening. */
._eg_st_live ._eg_st_sum_count {
  background: #fffbeb;
  color: #92400e;
  box-shadow: inset 0 0 0 1px #fcd34d;
}
._eg_st_live ._eg_st_sum_label::after {
  content: "";
  display: inline-block;
  width: 5px;
  height: 5px;
  margin-left: 7px;
  border-radius: 50%;
  background: #c9a227;
  vertical-align: middle;
  animation: _eg_pulse 1.4s ease-in-out infinite;
}
._eg_st_panel[open] ._eg_st_summary { border-bottom: 1px solid #f1f5f9; }
._eg_st_box {
  max-height: 230px;
  overflow-y: auto;
  padding: 10px 12px 12px;
  background: #fff;
}
._eg_st_box::-webkit-scrollbar { width: 6px; }
._eg_st_box::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 3px; }

._eg_st_row {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}
/* The rail: a continuous hairline with the dot sitting on it. */
._eg_st_rail {
  position: relative;
  flex: 0 0 auto;
  width: 9px;
  align-self: stretch;
}
._eg_st_rail::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 0;
  bottom: -2px;
  width: 1px;
  background: #e8edf3;
}
._eg_st_row:last-child ._eg_st_rail::before { bottom: auto; height: 9px; }
._eg_st_dot {
  position: absolute;
  left: 1px;
  top: 6px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #fff;
  box-shadow: inset 0 0 0 1.5px #cbd5e1;
}
._eg_st_body {
  flex: 1 1 auto;
  min-width: 0;
  padding: 1px 0 9px;
}
._eg_st_text {
  display: block;
  font: 500 12px/1.45 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #334155;
  word-break: break-word;
}
._eg_st_detail {
  display: block;
  margin-top: 2px;
  font: 400 11px/1.45 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #94a3b8;
  word-break: break-word;
  opacity: 0;
  transform: translateY(-1px);
  transition: opacity .18s ease, transform .18s ease;
}
._eg_st_detail._eg_st_in { opacity: 1; transform: none; }

/* Kinds. A stage is a heading; found/ok are progress; warn wants a look. */
._eg_st_stage ._eg_st_text {
  font-weight: 800;
  color: #0f172a;
  letter-spacing: -0.01em;
}
._eg_st_stage ._eg_st_dot { box-shadow: inset 0 0 0 3.5px #1e3a8a; }
._eg_st_found ._eg_st_dot,
._eg_st_ok ._eg_st_dot { box-shadow: inset 0 0 0 3.5px #10b981; }
._eg_st_warn ._eg_st_dot { box-shadow: inset 0 0 0 3.5px #d97706; }
._eg_st_warn ._eg_st_text { color: #78350f; font-weight: 600; }
._eg_st_warn ._eg_st_detail { color: #b48a5a; }

/* Each row slides in as it is revealed. */
._eg_st_new { animation: _eg_st_slide .22s ease-out both; }
@keyframes _eg_st_slide {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: none; }
}
/* The line being typed carries a caret. */
._eg_st_row:last-child ._eg_st_text::after {
  content: "";
  display: inline-block;
  width: 2px;
  height: 11px;
  margin-left: 2px;
  background: #c9a227;
  vertical-align: -1px;
  animation: _eg_st_caret 1s step-end infinite;
}
._eg_st_panel:not(._eg_st_live) ._eg_st_row:last-child ._eg_st_text::after {
  display: none;
}
@keyframes _eg_st_caret {
  0%, 50% { opacity: 1; }
  51%, 100% { opacity: 0; }
}
/* "There is more coming." A caret alone reads as finished, so while the run
   is working a waiting row sits under the feed saying what it is on. */
._eg_st_waitrow ._eg_st_dot {
  box-shadow: inset 0 0 0 1.5px #c9a227;
  animation: _eg_st_pulse 1.4s ease-in-out infinite;
}
/* The feed follows this row, so the gap it reserves below itself is what
   keeps the newest line off the bottom edge of the chat. */
._eg_st_waitrow { scroll-margin-bottom: 72px; }
._eg_st_wait {
  display: inline-flex;
  align-items: baseline;
  gap: 1px;
  font: 500 11.5px/1.45 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #8a6d16;
}
._eg_st_ell { display: inline-flex; gap: 2px; margin-left: 3px; }
._eg_st_ell b {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #c9a227;
  animation: _eg_st_bounce 1.2s ease-in-out infinite;
}
._eg_st_ell b:nth-child(2) { animation-delay: .16s; }
._eg_st_ell b:nth-child(3) { animation-delay: .32s; }
@keyframes _eg_st_bounce {
  0%, 60%, 100% { opacity: .25; transform: translateY(0); }
  30%           { opacity: 1;   transform: translateY(-2px); }
}
@keyframes _eg_st_pulse {
  0%, 100% { box-shadow: inset 0 0 0 1.5px #c9a227; }
  50%      { box-shadow: inset 0 0 0 3.5px #c9a227; }
}
/* The rail runs on down to the waiting row instead of stopping short. */
._eg_st_waiting #_eg_stream_rows ._eg_st_row:last-child ._eg_st_rail::before {
  bottom: -2px;
  height: auto;
}

/* ─── Staged arrival of the review panels ──────────────────────────────
 * Opacity only. The page is laid out in full from the first frame, so
 * nothing reflows under the reader as each panel comes in. */
._eg_rv { transition: opacity .3s ease, transform .3s ease; }
._eg_rv._eg_rv_hide { opacity: 0; transform: translateY(6px); }
/* ─── Head of the proposed revisions ───────────────────────────────────
 * The action first, on the left, where the eye starts — then the heading
 * and a plain-language count. A bare uppercase label with a button
 * floating after it read as a form, not as a list you act on. */
._eg_prop_head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 14px 0 0;
  padding: 11px 13px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #c9a227;
}
._eg_prop_head ._eg_btn_apply { flex: 0 0 auto; }
._eg_prop_titles { min-width: 0; }
._eg_prop_title {
  font: 800 14px/1.25 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: -0.015em;
  color: #0f172a;
}
._eg_prop_sub {
  margin-top: 2px;
  font: 400 11.5px/1.4 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #64748b;
}
._eg_prop_hint {
  margin: 6px 0 2px;
  font: 400 11.5px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #94a3b8;
}

/* ─── Follow up ────────────────────────────────────────────────────────
 * Loose ends, not edits. Deliberately not amber — these are notes to
 * work down, not warnings about the redlines. */
._eg_fu_panel {
  margin: 10px 0;
  padding: 0 0 6px;
  border: 1px solid #cbd5e1;
  background: #fff;
}
._eg_fu_summary {
  padding: 8px 11px;
  font: 800 10px/1.2 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .09em;
  text-transform: uppercase;
  color: #334155;
  cursor: pointer;
  user-select: none;
}
._eg_fu_sub {
  padding: 0 11px 6px;
  font: 400 11px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #64748b;
}
._eg_fu_row {
  display: flex;
  gap: 8px;
  align-items: baseline;
  padding: 4px 11px;
  border-top: 1px solid #f1f5f9;
  font: 400 11.5px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #475569;
}
._eg_fu_where {
  flex: 0 0 auto;
  min-width: 92px;
  font-weight: 700;
  color: #334155;
}
._eg_fu_what { flex: 1 1 auto; }

/* Click-to-locate card + per-card Apply */
._eg_card_clickloc { cursor: pointer; }
._eg_card_clickloc:hover { border-color: #94a3b8; }

._eg_card_done {
  font: 700 10px/1.4 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: #059669;
  padding: 3px 6px;
}
._eg_card_applied { opacity: .6; }
._eg_stat_applied {
  background: #ecfdf5;
  border-color: #a7f3d0;
  color: #065f46;
  font-weight: 700;
}
._eg_actions_top {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-top: 0;
}
._eg_apply_hint {
  font: 400 11px/1.4 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #94a3b8;
}

/* ─── Edits waiting on a human ─────────────────────────────────────────
 * Amber and above the cards. The bulk-accept button skips these, so if
 * they are not conspicuous the clause looks untouched for no reason. */
._eg_nd_box {
  margin: 10px 0;
  padding: 9px 11px;
  background: #fffbeb;
  border: 1px solid #fcd34d;
  border-left: 3px solid #d97706;
}
._eg_nd_head {
  font: 800 10px/1.2 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .09em;
  text-transform: uppercase;
  color: #92400e;
}
._eg_nd_sub {
  margin: 4px 0 6px;
  font: 400 11px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #78350f;
}
._eg_nd_row {
  display: flex;
  gap: 8px;
  align-items: baseline;
  padding: 4px 0;
  border-top: 1px solid rgba(120, 53, 15, .13);
  font: 400 11.5px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #78350f;
  cursor: pointer;
}
._eg_nd_row:hover { background: rgba(217, 119, 6, .07); }
._eg_nd_where {
  flex: 0 0 auto;
  min-width: 96px;
  font-weight: 700;
  color: #92400e;
}
._eg_nd_why { flex: 1 1 auto; }
._eg_stat_review {
  background: #fffbeb;
  border-color: #fcd34d;
  color: #92400e;
  font-weight: 700;
}
._eg_skip_note {
  font-weight: 400;
  opacity: .75;
}

/* ─── Proposal audit (what the two halves did to the plan) ─────────────
 * Neutral slate: these are things that HAPPENED, not warnings. The rows
 * that need a second look carry the amber themselves. */
._eg_cf_box {
  margin: 10px 0;
  padding: 9px 11px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #64748b;
}
._eg_cf_head {
  font: 800 10px/1.2 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .09em;
  text-transform: uppercase;
  color: #64748b;
  margin-bottom: 5px;
}
._eg_cf_row {
  display: flex;
  gap: 7px;
  margin-top: 4px;
  font: 400 11.5px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #475569;
}
._eg_cf_label {
  flex: 0 0 auto;
  min-width: 118px;
  font-weight: 700;
  color: #334155;
}
._eg_cf_items { flex: 1 1 auto; }
._eg_cf_warn ._eg_cf_label { color: #b45309; }
._eg_cf_warn ._eg_cf_items { color: #78350f; }

/* The per-card note — what the audit said about THIS edit. */
._eg_card_audit {
  margin: 6px 0 0;
  padding: 6px 8px;
  background: #fffbeb;
  border-left: 2px solid #d97706;
  font: 400 11px/1.45 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #78350f;
}
._eg_card_audit_tag {
  display: inline-block;
  margin-right: 5px;
  padding: 1px 5px;
  border-radius: 2px;
  background: #fde68a;
  font: 800 9px/1.4 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: #78350f;
}

/* ─── Coverage audit (requirements checklist) ──────────────────────────
 * A scored checklist, not a verdict. Amber when something is unmet,
 * green when everything is — the frame carries the state so the rows
 * only have to carry the per-item mark. */
._eg_audit_box,
._eg_audit_box_ok {
  margin: 10px 0;
  padding: 10px 12px;
  background: #fffbeb;
  border: 1px solid #fcd34d;
  border-left: 3px solid #d97706;
}
._eg_audit_box_ok {
  background: #ecfdf5;
  border-color: #a7f3d0;
  border-left-color: #059669;
}
._eg_audit_head {
  font: 700 11.5px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #78350f;
}
._eg_audit_box_ok ._eg_audit_head { color: #065f46; }
._eg_audit_count {
  display: inline-block;
  margin-left: 6px;
  padding: 1px 6px;
  border-radius: 9px;
  background: rgba(120, 53, 15, .1);
  font: 800 9.5px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .05em;
  text-transform: uppercase;
  white-space: nowrap;
}
._eg_audit_box_ok ._eg_audit_count { background: rgba(6, 95, 70, .1); }
._eg_audit_row {
  display: flex;
  gap: 6px;
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid rgba(120, 53, 15, .13);
  font: 400 11.5px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
}
._eg_audit_box_ok ._eg_audit_row { border-top-color: rgba(6, 95, 70, .13); }
._eg_audit_mark {
  flex: 0 0 auto;
  width: 11px;
  font-weight: 800;
}
._eg_audit_ok ._eg_audit_mark { color: #059669; }
._eg_audit_gap ._eg_audit_mark { color: #b45309; }
._eg_audit_text { flex: 1 1 auto; color: #44403c; }
._eg_audit_gap ._eg_audit_text { color: #78350f; font-weight: 600; }
._eg_audit_text em {
  font-style: normal;
  font-size: 10px;
  color: #a8a29e;
  letter-spacing: .03em;
  text-transform: uppercase;
}
._eg_audit_text b { font-weight: 700; }
._eg_audit_note {
  margin-top: 2px;
  font-weight: 400;
  color: #57534e;
}
._eg_audit_ev {
  margin-top: 2px;
  padding-left: 7px;
  border-left: 2px solid #e7e5e4;
  font: 400 10.5px/1.5 ui-monospace, Consolas, monospace;
  color: #78716c;
}

/* Apply-failure diagnostics — which Word call threw, and what it was
 * handed. "InvalidArgument" alone is unactionable; these failures are
 * hard to reproduce, so the record has to be in the UI. */
._eg_fail_detail {
  margin-top: 4px;
  font: 500 10px/1.4 ui-monospace, Consolas, monospace;
  color: #92400e;
  opacity: .85;
}

/* Coverage-pass badge — an edit the planner never proposed, surfaced only
 * by reading the document as it would read after the other edits. */
._eg_coverage_badge {
  display: inline-block;
  margin-left: 5px;
  padding: 2px 6px;
  background: #f5f3ff;
  border: 1px solid #ddd6fe;
  color: #5b21b6;
  font: 800 8.5px/1 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .09em;
}

/* Clicking a card whose anchor cannot be found — the only failure
   feedback left now that the card is the click target. */
._eg_card_lost {
  animation: _eg_card_lost_anim 1.2s ease-out;
}
@keyframes _eg_card_lost_anim {
  0%   { background: #fef2f2; border-color: #ef4444; }
  100% { background: transparent; }
}

/* Severity dot on a proactive follow-up item. Only these carry one —
   the deterministic findings are facts, not graded observations. */
._eg_fu_dot {
  flex: 0 0 auto;
  width: 6px;
  height: 6px;
  margin-top: 6px;
  border-radius: 50%;
  background: #cbd5e1;
}
._eg_fu_high ._eg_fu_dot { background: #dc2626; }
._eg_fu_med ._eg_fu_dot  { background: #d97706; }
._eg_fu_low ._eg_fu_dot  { background: #94a3b8; }
._eg_fu_high ._eg_fu_what { color: #0f172a; font-weight: 600; }

/* ─── The "I need an answer" header ────────────────────────────────────
 * The clarify screen is the only one that asks the reader FOR something,
 * inside a chat otherwise full of ELI telling them things. A question
 * mark, a sentence-case heading and a gold frame, so it does not read as
 * one more status panel. */
._eg_ask_head {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  margin: 10px 0 2px;
  padding: 13px 15px;
  background: #fffdf5;
  border: 1px solid #e8d89a;
  border-left: 3px solid #c9a227;
}
._eg_ask_mark {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: #c9a227;
  color: #fff;
  font: 800 15px/1 Inter, 'Segoe UI', system-ui, sans-serif;
}
._eg_ask_title {
  font: 800 14px/1.3 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: -0.015em;
  color: #6b5312;
}
._eg_ask_sub {
  margin-top: 3px;
  font: 400 11.5px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #8a7433;
}
/* The questions themselves sit in a rail under the header, so the block
   reads as one thing being asked rather than a run of loose cards. */
._eg_ask_list {
  padding-left: 11px;
  border-left: 2px solid #f0e6c4;
}
._eg_ask_list ._eg_clar_q { font-size: 13.5px; }

/* "Waiting for you" — says plainly that nothing proceeds until they act. */
._eg_ask_pill {
  display: inline-block;
  margin-left: 8px;
  padding: 2px 8px;
  border-radius: 9px;
  background: #c9a227;
  color: #fff;
  font: 800 9px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .09em;
  text-transform: uppercase;
  vertical-align: 2px;
  animation: _eg_pulse 1.8s ease-in-out infinite;
}

/* Per-question state. Amber "needs your answer" until there is text in
   the box, then green — flipped live by the input handler. */
._eg_clar_state {
  margin-top: 7px;
  font: 700 10px/1.4 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .04em;
  text-transform: uppercase;
}
._eg_clar_todo { color: #b45309; }
._eg_clar_ok { display: none; color: #059669; }
._eg_clar_done ._eg_clar_todo { display: none; }
._eg_clar_done ._eg_clar_ok { display: inline; }
/* The card carries it too, so a glance down the list shows what is left. */
._eg_clar_row { border-left: 3px solid #e8d89a; }
._eg_clar_done { border-left-color: #10b981; background: #fbfefc; }
._eg_clar_done ._eg_clar_input { border-color: #a7f3d0; }

/* Ask ELI's own input while the agent is waiting on an answer. Greyed so
   the send arrow beside it does not look like the way forward — pressing
   it would post the answer as a new question instead. Released on every
   render that is not the question screen, and on close. */
._eg_ask_locked {
  opacity: .45 !important;
  cursor: not-allowed !important;
  pointer-events: none !important;
}

/* "Your turn" — a rule across the panel between what ELI did (the feed
   above) and what the reader does (the cards below). The handover was
   invisible: the activity just stopped and edits appeared under it. */
._eg_turn {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 16px 0 10px;
  /* Arriving at the review scrolls here. Land a little above the line so
     "YOUR TURN" is read as a handover and not as the top edge of a pane. */
  scroll-margin-top: 28px;
}
._eg_turn::before,
._eg_turn::after {
  content: "";
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, #e2e8f0 35%, #e2e8f0 65%, transparent);
}
._eg_turn span {
  flex: 0 0 auto;
  padding: 3px 11px;
  border: 1px solid #e8d89a;
  border-radius: 11px;
  background: #fffdf5;
  font: 800 9.5px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #8a6d16;
}

/* In the chat the transcript is the scroll region. A second scrollbar
   inside the feed meant the newest line could be at the bottom of a box
   that was itself off screen — so in-chat the feed grows and the chat
   scrolls, which is the one the reader is already using. */
._eg_body_chat ._eg_st_box {
  max-height: none;
  overflow: visible;
}

/* Must-do vs optional. The panel turns amber only when there is something
   to fix — a clean run should not look like a to-do list. */
._eg_fu_has_must {
  border-color: #fcd34d;
  border-left: 3px solid #d97706;
}
._eg_fu_has_must ._eg_fu_summary { color: #92400e; }
._eg_fu_has_must ._eg_fu_sub { color: #78350f; }
/* Suggestions: collapsed, quiet, and clearly separate from the must-dos. */
._eg_fu_more {
  margin: 8px 11px 2px;
  border-top: 1px solid #f1f5f9;
  padding-top: 6px;
}
._eg_fu_more_sum {
  font: 600 11px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  color: #94a3b8;
  cursor: pointer;
  user-select: none;
  padding: 2px 0;
}
._eg_fu_more_sum:hover { color: #64748b; }
._eg_fu_more ._eg_fu_row { padding-left: 0; padding-right: 0; }

/* "Your turn" beside the heading, so the handover is stated where the
   reader's eye lands rather than only on the rule above it. */
._eg_prop_turn {
  display: inline-block;
  margin-left: 9px;
  padding: 2px 8px;
  border-radius: 9px;
  background: #c9a227;
  color: #fff;
  font: 800 9px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .09em;
  text-transform: uppercase;
  vertical-align: 2px;
}
._eg_prop_titles { flex: 1 1 auto; min-width: 0; }

/* ─── ELI's playbook ───────────────────────────────────────────────────
 * Navy like the other "what ELI did" panels, with the tier carried in a
 * pill. Mandatory is the only one that gets the alarm colour. */
._eg_pb_box {
  margin: 10px 0;
  padding: 10px 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #1e3a8a;
}
._eg_pb_head {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font: 800 10px/1.4 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: #1e3a8a;
}
._eg_pb_count {
  margin-left: auto;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
  color: #64748b;
}
._eg_pb_empty {
  margin-top: 6px;
  font-size: 11px;
  line-height: 1.5;
  color: #64748b;
}
._eg_pb_row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 7px;
}
._eg_pb_tier {
  flex: 0 0 auto;
  min-width: 62px;
  padding: 2px 6px;
  border-radius: 2px;
  text-align: center;
  font: 800 8.5px/1.5 Inter, 'Segoe UI', system-ui, sans-serif;
  letter-spacing: .08em;
  text-transform: uppercase;
  background: #eef2f7;
  color: #64748b;
}
._eg_pb_mandatory { background: #fee2e2; color: #991b1b; }
._eg_pb_strong    { background: #ffedd5; color: #b45309; }
._eg_pb_default   { background: #ccfbf1; color: #0f766e; }
._eg_pb_advisory  { background: #f1f5f9; color: #64748b; }
._eg_pb_text {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 11px;
  line-height: 1.5;
  color: #334155;
  word-wrap: break-word;
}
._eg_pb_clause {
  font-family: monospace;
  font-size: 10px;
  color: #64748b;
}

/* The concrete gap under a hand-over instruction — "lacks a notice block for
   Company 2". Folded in from the checklist rather than printed as its own
   row saying the same thing again. */
._eg_fu_detail {
  display: block;
  margin-top: 3px;
  font-size: 10.5px;
  line-height: 1.45;
  color: #8a6d16;
}

/* A checklist requirement that is YOURS, not a gap in the agent's work:
   a notice or signature block, which ELI does not edit. Gold, like the
   other "your turn" surfaces — not the red of a failure. */
._eg_audit_hand ._eg_audit_mark { color: #8a6d16; }
._eg_audit_hand ._eg_audit_text b { color: #8a6d16; font-weight: 700; }

/* Clause library panel (Manage Agents). Neutral + the gold accent only —
   no third colour beyond the amber used for an un-indexed source. */
._eg_cl_list {
  margin: 8px 0 6px 0;
  padding-left: 16px;
  font-size: 11px;
  color: #334155;
  line-height: 1.6;
}
._eg_cl_list b { font-weight: 700; color: #0f172a; }
._eg_cl_dim { font-size: 10px; color: #64748b; }
._eg_cl_warn {
  margin: 8px 0;
  padding: 7px 9px;
  border-left: 2px solid #c9a227;
  background: #fdfaf0;
  font-size: 10.5px;
  color: #6b5510;
  line-height: 1.55;
  border-radius: 0 3px 3px 0;
}
._eg_cl_diag {
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px dashed #e2d9b8;
  font: 10px/1.6 ui-monospace, SFMono-Regular, Menlo, monospace;
  color: #6b5510;
}
._eg_cl_diag_samples { margin-top: 4px; }
._eg_cl_diag_samples > div {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Research agent. The badge carries the only colour decision that matters:
   whether this is ELI's position or general knowledge. */
._eg_rs_badge {
  margin: 0 0 12px 0;
  padding: 8px 11px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 700;
  line-height: 1.5;
}
._eg_rs_onfile { background: #fdfaf0; border-left: 3px solid #c9a227; color: #6b5510; }
._eg_rs_general { background: #f8fafc; border-left: 3px solid #94a3b8; color: #475569; }
._eg_rs_answer { font-size: 12px; line-height: 1.65; color: #1e293b; }
._eg_rs_answer p { margin: 0 0 10px 0; }
._eg_rs_answer ul { margin: 0 0 10px 0; padding-left: 18px; }
._eg_rs_answer li { margin: 0 0 4px 0; }
._eg_rs_answer code {
  font: 600 11px ui-monospace, SFMono-Regular, Menlo, monospace;
  background: #f1f5f9;
  padding: 1px 4px;
  border-radius: 3px;
}
._eg_rs_cites { margin-top: 14px; border-top: 1px solid #e2e8f0; padding-top: 10px; }
._eg_rs_cites_h {
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: #64748b;
  margin-bottom: 7px;
}
._eg_rs_cite { margin-bottom: 8px; font-size: 11px; line-height: 1.55; }
._eg_rs_cite_src { font-weight: 700; color: #0f172a; }
._eg_rs_tier {
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: #6b5510;
  background: #fdfaf0;
  padding: 1px 5px;
  border-radius: 999px;
  margin-left: 5px;
}
._eg_rs_cite_what { color: #475569; }
._eg_rs_gap {
  margin-top: 12px;
  padding: 8px 10px;
  background: #f8fafc;
  border-left: 2px solid #cbd5e1;
  font-size: 11px;
  line-height: 1.55;
  color: #475569;
  border-radius: 0 3px 3px 0;
}
._eg_rs_fu { margin-top: 14px; }
._eg_rs_fu_q {
  font-size: 11px;
  color: #475569;
  padding: 4px 0;
  line-height: 1.5;
}

/* Where a drafted section's language came from. Gold = our own reviewed
   language, neutral = the model wrote it. No third colour. */
._eg_src_badge {
  display: inline-block;
  margin-left: 6px;
  padding: 1px 6px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  vertical-align: middle;
  white-space: nowrap;
}
._eg_src_locked { background: #c9a227; color: #2b2205; }
._eg_src_playbook { background: #fdfaf0; color: #6b5510; border: 1px solid #e6d9a8; }
._eg_src_template { background: #f5f7fa; color: #334155; border: 1px solid #cbd5e1; }
._eg_src_adapt { background: #f8fafc; color: #64748b; border: 1px dashed #cbd5e1; }
._eg_src_generate { background: #fff; color: #94a3b8; border: 1px dashed #e2e8f0; }
._eg_src_summary {
  margin: 8px 0 12px 0;
  padding: 9px 11px;
  background: #fdfaf0;
  border-left: 3px solid #c9a227;
  border-radius: 0 4px 4px 0;
}
._eg_src_headline { font-size: 11.5px; font-weight: 700; color: #6b5510; }
._eg_src_tiers { margin-top: 6px; display: flex; flex-wrap: wrap; gap: 4px; align-items: center; }
._eg_src_tiers b { font-size: 10px; color: #475569; margin-right: 6px; }
._eg_src_gaps {
  margin-top: 7px;
  padding-top: 7px;
  border-top: 1px dashed #e6d9a8;
  font-size: 10.5px;
  line-height: 1.55;
  color: #6b5510;
}
._eg_outline_src {
  font-size: 9.5px;
  color: #94a3b8;
  margin-top: 2px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
._eg_md_h {
  display: block;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #0f172a;
  margin: 12px 0 5px 0;
}
._eg_md_q {
  margin: 8px 0;
  padding: 8px 11px;
  border-left: 3px solid #c9a227;
  background: #fdfaf0;
  font-size: 11px;
  line-height: 1.6;
  color: #3f3208;
  border-radius: 0 3px 3px 0;
}
._eg_rs_ref {
  font-size: 8.5px;
  font-weight: 800;
  color: #6b5510;
  background: #fdfaf0;
  border: 1px solid #e6d9a8;
  border-radius: 999px;
  padding: 0 4px;
  margin-left: 2px;
  vertical-align: super;
  line-height: 1.4;
}
._eg_rs_refnum {
  display: inline-block;
  min-width: 15px;
  height: 15px;
  line-height: 15px;
  text-align: center;
  font-size: 9px;
  font-weight: 800;
  color: #6b5510;
  background: #fdfaf0;
  border: 1px solid #e6d9a8;
  border-radius: 999px;
  margin-right: 6px;
}

/* Draft checks + the pre-insert verification panel. */
._eg_verify_panel {
  margin: 0 0 14px 0;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #c9a227;
  border-radius: 0 4px 4px 0;
  background: #fff;
}
._eg_verify_head {
  padding: 8px 11px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #6b5510;
  background: #fdfaf0;
  border-bottom: 1px solid #f0e7c8;
}
._eg_verify_row {
  display: flex;
  gap: 10px;
  padding: 7px 11px;
  border-bottom: 1px solid #f1f5f9;
}
._eg_verify_row:last-child { border-bottom: none; }
._eg_verify_k {
  flex: 0 0 34%;
  font-size: 10.5px;
  font-weight: 700;
  color: #0f172a;
  line-height: 1.5;
}
._eg_verify_v { flex: 1; font-size: 10.5px; color: #475569; line-height: 1.55; }
._eg_dc_row {
  padding: 7px 10px;
  margin-bottom: 5px;
  border-radius: 3px;
  background: #f8fafc;
  border-left: 2px solid #cbd5e1;
}
._eg_dc_blocker { background: #fdfaf0; border-left-color: #c9a227; }
._eg_dc_tag {
  display: inline-block;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #64748b;
  margin-bottom: 3px;
}
._eg_dc_blocker ._eg_dc_tag { color: #6b5510; }
._eg_dc_what { font-size: 11px; color: #1e293b; line-height: 1.55; }
._eg_dc_where { color: #94a3b8; }
._eg_dc_detail {
  margin-top: 3px;
  font: 9.5px/1.5 ui-monospace, SFMono-Regular, Menlo, monospace;
  color: #94a3b8;
  word-break: break-word;
}
._eg_fu_item {
  padding: 8px 11px;
  margin-bottom: 5px;
  background: #fdfaf0;
  border-left: 3px solid #c9a227;
  border-radius: 0 3px 3px 0;
  font-size: 11px;
  line-height: 1.6;
  color: #4a3a0b;
}
._eg_src_added { background: #0f172a; color: #e2e8f0; }

/* The approach panel — ELI's reading of the request before it drafts.
   This is meant to be read, so it gets room: neutrals plus the gold
   accent, no third colour beyond the amber used for risks. */
._eg_ap_panel {
  margin: 10px 0 12px 0;
  padding: 11px 13px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #c9a227;
  border-radius: 0 4px 4px 0;
}
._eg_ap_understand {
  font-size: 12px;
  font-weight: 700;
  line-height: 1.55;
  color: #0f172a;
  margin-bottom: 10px;
  padding-bottom: 9px;
  border-bottom: 1px solid #f1f5f9;
}
._eg_ap_item { margin-bottom: 9px; }
._eg_ap_head {
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #6b5510;
  margin-bottom: 2px;
}
._eg_ap_detail { font-size: 11.5px; line-height: 1.6; color: #334155; }
._eg_ap_block {
  margin-top: 10px;
  padding-top: 9px;
  border-top: 1px solid #f1f5f9;
}
._eg_ap_blockh {
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #64748b;
  margin-bottom: 4px;
}
._eg_ap_li {
  font-size: 11px;
  line-height: 1.6;
  color: #475569;
  padding-left: 12px;
  position: relative;
}
._eg_ap_li::before {
  content: "\2022";
  position: absolute;
  left: 2px;
  color: #c9a227;
}
._eg_ap_risks ._eg_ap_li::before { color: #b08f1f; }
._eg_ap_scale {
  margin-top: 10px;
  padding-top: 9px;
  border-top: 1px solid #f1f5f9;
  font-size: 10.5px;
  line-height: 1.55;
  color: #64748b;
}
._eg_ap_scaletag {
  display: inline-block;
  margin-right: 6px;
  padding: 1px 6px;
  border-radius: 999px;
  background: #fdfaf0;
  border: 1px solid #e6d9a8;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #6b5510;
}
._eg_ap_fold { padding: 0; }
._eg_ap_fold > ._eg_ap_understand,
._eg_ap_fold > ._eg_ap_item,
._eg_ap_fold > ._eg_ap_block,
._eg_ap_fold > ._eg_ap_scale { margin-left: 13px; margin-right: 13px; }
._eg_ap_fold > ._eg_ap_scale { padding-bottom: 11px; }
._eg_ap_sum {
  cursor: pointer;
  padding: 9px 13px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #6b5510;
  list-style: none;
}
._eg_ap_sum::-webkit-details-marker { display: none; }
._eg_ap_sumn {
  display: inline-block;
  margin-left: 5px;
  padding: 0 5px;
  border-radius: 999px;
  background: #fdfaf0;
  border: 1px solid #e6d9a8;
  font-size: 9px;
}
._eg_applied_fmt {
  margin-top: 3px;
  font-size: 9.5px;
  color: #94a3b8;
  line-height: 1.5;
}

/* Enrichment now runs alongside the review, so the section it fills says
   it is still working rather than appearing from nowhere. */
._eg_un_pending {
  margin: 10px 0;
  padding: 8px 11px;
  background: #f8fafc;
  border-left: 2px solid #cbd5e1;
  border-radius: 0 3px 3px 0;
  font-size: 10.5px;
  line-height: 1.55;
  color: #64748b;
}
._eg_un_dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  margin-right: 7px;
  border-radius: 50%;
  background: #c9a227;
  animation: _eg_un_pulse 1.4s ease-in-out infinite;
}
@keyframes _eg_un_pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: .3; }
}
